window.QUEST_BANK={"4":{"math":[["What is 248 + 137?",["375","385","395","285"],1,"Add ones (8+7), tens, then hundreds.","Cộng lần lượt hàng đơn vị, chục và trăm.","Tách 248 và 137 theo hàng trăm, chục, đơn vị."],["A rectangle is 8 cm long and 5 cm wide. What is its perimeter?",["13 cm","26 cm","40 cm","20 cm"],1,"Perimeter is 2 × (8 + 5) = 26 cm.","Chu vi là tổng bốn cạnh: (8+5)×2.","Chu vi là độ dài đường viền; có bao nhiêu cạnh cần cộng?"],["Which fraction is equal to 1/2?",["2/6","3/8","4/8","5/12"],2,"Four of eight equal parts is one half.","4/8 rút gọn được 1/2.","Phân số bằng một nửa khi tử số bằng nửa mẫu số."],["There are 6 boxes with 7 pencils each. How many pencils?",["36","42","49","13"],1,"Six groups of seven is 6 × 7 = 42.","Sáu hộp, mỗi hộp 7 cây: 6×7.","Mỗi hộp có 7 bút; có bao nhiêu nhóm 7?"],["What is 604 − 278?",["326","426","336","382"],0,"Regroup and subtract: 604 − 278 = 326.","Đặt tính và mượn khi cần: 604 − 278 = 326.","Bắt đầu ở hàng đơn vị; có cần mượn từ hàng cao hơn không?"],["What is 9 × 8?",["72","64","81","17"],0,"Eight groups of nine contain 72.","8 nhóm, mỗi nhóm 9: 9 × 8 = 72.","Nhớ bảng nhân 8 hoặc cộng 9 tám lần."],["What is 84 ÷ 7?",["12","11","14","13"],0,"Since 7 × 12 = 84, the quotient is 12.","Vì 7 × 12 = 84 nên 84 ÷ 7 = 12.","Tìm số nhân với 7 để bằng 84."],["A square has a side of 6 m. What is its area?",["36 m²","24 m²","12 m²","30 m²"],0,"Area = 6 × 6 = 36 square meters.","Diện tích hình vuông = cạnh × cạnh = 6 × 6 = 36 m².","Diện tích hình vuông bằng cạnh nhân cạnh."],["Which fraction is greater than 1/4?",["3/4","1/8","1/5","1/6"],0,"3/4 and 1/4 have the same denominator, and 3 > 1. The other choices (1/8, 1/5, 1/6) are all smaller than 1/4.","3/4 và 1/4 cùng mẫu số 4; tử số 3 lớn hơn 1 nên 3/4 lớn hơn 1/4. Các lựa chọn còn lại (1/8, 1/5, 1/6) đều nhỏ hơn 1/4.","Phân số có tử là 1: mẫu càng lớn thì phân số càng nhỏ. Phân số nào có tử lớn hơn 1?"],["Round 4,763 to the nearest hundred.",["4,800","4,700","4,760","5,000"],0,"The tens digit is 6, so round the hundreds digit up.","Chữ số hàng chục là 6 (≥ 5) nên làm tròn lên: 4.763 ≈ 4.800.","Nhìn chữ số hàng chục để làm tròn hàng trăm."],["Which number is a multiple of 9?",["63","62","64","65"],0,"Nine times seven equals 63.","9 × 7 = 63 nên 63 là bội của 9.","Thử bảng nhân 9 để xem số nào thuộc bảng."],["A movie starts at 2:15 and lasts 90 minutes. When does it end?",["3:45","3:15","4:15","2:45"],0,"Ninety minutes is one hour and thirty minutes; 2:15 + 1:30 = 3:45.","90 phút = 1 giờ 30 phút; 2:15 + 1:30 = 3:45.","Đổi 90 phút thành 1 giờ 30 phút rồi cộng vào giờ bắt đầu."],["What is 0.4 + 0.3?",["0.7","0.12","0.43","7.0"],0,"Four tenths plus three tenths is seven tenths.","4 phần mười + 3 phần mười = 7 phần mười = 0,7.","Cộng các phần mười, đừng ghép chữ số cạnh nhau."],["A box has 24 markers shared equally by 6 children. How many each?",["4","6","18","3"],0,"24 ÷ 6 = 4 markers per child.","24 ÷ 6 = 4, mỗi bạn được 4 cây bút.","Chia đều 24 thành 6 nhóm bằng nhau."],["Which is an acute angle?",["45°","90°","120°","180°"],0,"An acute angle measures less than 90 degrees.","Góc nhọn là góc nhỏ hơn 90°, nên 45° là góc nhọn.","Góc nhọn nhỏ hơn 90 độ."],["What is 3,000 + 400 + 20 + 5?",["3,425","3,245","3,452","3,405"],0,"The expanded form gives 3,425.","3.000 + 400 + 20 + 5 = 3.425 (3 nghìn, 4 trăm, 2 chục, 5 đơn vị).","Ghép hàng nghìn, trăm, chục, đơn vị theo đúng vị trí."]],"science":[["Which part of a plant absorbs most water from the soil?",["Flower","Roots","Leaves","Fruit"],1,"Roots take in water and minerals from the soil.","Rễ cây hấp thụ nước và khoáng từ đất.","Hãy tìm bộ phận nằm dưới đất, tiếp xúc với nước."],["What causes day and night on Earth?",["The Moon moving","Earth rotating","Clouds moving","The seasons"],1,"Earth rotates once about every 24 hours.","Trái Đất tự quay tạo ngày và đêm.","Ngày và đêm đổi nhau vì Trái Đất thực hiện chuyển động nào?"],["Which change is caused by heating ice?",["Freezing","Melting","Magnetism","Evaporation of stone"],1,"Ice becomes liquid water when it melts.","Nước đá tan thành nước lỏng.","Nước đá gặp nhiệt sẽ thay đổi trạng thái ra sao?"],["What carries sound to your ears through the air?",["Vibrations","Shadows","Sunlight","Magnets"],0,"Sound travels as vibrations through matter.","Âm thanh truyền qua dao động trong môi trường.","Âm thanh cần dao động để truyền qua không khí."],["Which material dissolves easily in water?",["Table salt","Pebbles","Plastic beads","Dry sand"],0,"Salt dissolves and spreads through water.","Muối ăn tan trong nước và hòa đều vào nước.","Thử nghĩ vật nào biến mất khỏi mắt khi khuấy vào nước."],["What is needed for a shadow to form?",["A light source and an object","Only air","Only water","Sound and heat"],0,"An object blocks light, creating a shadow.","Cần có nguồn sáng và một vật cản ánh sáng thì mới có bóng.","Bóng xuất hiện khi ánh sáng bị vật gì cản lại?"],["Which energy source is renewable?",["Sunlight","Coal","Oil","Natural gas"],0,"Sunlight is continually replenished by the Sun.","Ánh sáng Mặt Trời được bổ sung liên tục nên là năng lượng tái tạo; than, dầu, khí đốt sẽ cạn kiệt.","Nguồn năng lượng nào được bổ sung liên tục trong tự nhiên?"],["Which part of a flower often makes seeds after pollination?",["Ovary","Root hair","Stem bark","Leaf vein"],0,"Ovules in the flower's ovary can develop into seeds.","Noãn nằm trong bầu nhụy (ovary) của hoa sẽ phát triển thành hạt.","Hãy nghĩ về bộ phận sinh sản trong hoa."],["Why do we see the Moon change shape over a month?",["We see different sunlit portions","Earth changes size","The Moon melts","Clouds carve the Moon"],0,"Moon phases depend on viewing the illuminated half from Earth.","Mặt Trăng luôn được Mặt Trời chiếu sáng một nửa; tùy vị trí, ta thấy phần sáng đó nhiều hay ít nên trăng như đổi hình.","Mặt Trăng phát sáng do tự nó hay phản chiếu ánh sáng Mặt Trời?"],["Which object is attracted strongly by a typical magnet?",["Iron nail","Wooden spoon","Glass cup","Paper towel"],0,"Iron is a magnetic material.","Sắt là vật liệu có từ tính nên đinh sắt bị nam châm hút mạnh.","Vật nào làm bằng kim loại sắt?"],["Which is an example of erosion?",["A river carrying away soil","Ice cubes melting in a cup","A plant growing leaves","A magnet pulling a nail"],0,"Erosion moves weathered material by water, wind, or ice.","Xói mòn là khi nước, gió hoặc băng mang đất đá đi nơi khác, ví dụ dòng sông cuốn đất.","Xói mòn là đất đá bị mang đi hay chỉ vỡ tại chỗ?"],["Which tool measures air temperature?",["Thermometer","Compass","Balance","Ruler"],0,"A thermometer measures temperature.","Nhiệt kế dùng để đo nhiệt độ.","Dụng cụ nào có thang chia độ nóng lạnh?"],["What is a habitat?",["A place where an organism lives","A type of cloud","A kind of rock","A moon phase"],0,"A habitat provides surroundings and resources for an organism.","Môi trường sống là nơi sinh vật sống và tìm thức ăn, nước, chỗ trú.","Động vật tìm thức ăn, nước và chỗ trú ở đâu?"],["What is condensation?",["Gas changing into liquid","Solid changing to gas","Liquid changing to solid","A rock cracking"],0,"Condensation forms liquid droplets from water vapor.","Ngưng tụ là khí chuyển thành lỏng, ví dụ hơi nước đọng thành giọt trên kính lạnh.","Khi hơi nước chạm kính lạnh, chuyện gì xảy ra?"],["Why does the Sun appear to move across the sky?",["Earth rotates","The Sun orbits Earth daily","Clouds push the Sun","The Moon pulls the Sun"],0,"Earth's rotation changes the Sun's apparent position.","Trái Đất tự quay nên ta thấy Mặt Trời như di chuyển qua bầu trời.","Vì sao ta thấy Mặt Trời đổi vị trí trong ngày?"],["What is a good test of whether a plant needs light?",["Grow similar plants with and without light","Change light, water, soil all at once","Use different plant species and pots","Count leaves on one plant once"],0,"A fair test changes one variable while others remain alike.","Thí nghiệm công bằng chỉ thay đổi một yếu tố (ánh sáng), giữ các yếu tố khác giống nhau.","Thí nghiệm công bằng nên chỉ thay đổi bao nhiêu yếu tố?"]],"history":[["What is a primary source?",["A recent movie","A diary from the time","A modern textbook","A guessing game"],1,"A diary written during an event is first-hand evidence.","Nhật ký thời đó là nguồn tư liệu gốc.","Tư liệu được ghi ngay vào thời xảy ra sự kiện có đặc điểm gì?"],["Why do historians use timelines?",["To predict weather","To arrange events in order","To do multiplication","To find north"],1,"Timelines show the order in which events happened.","Dòng thời gian xếp sự kiện theo thứ tự.","Muốn biết sự kiện trước-sau, ta nên dùng công cụ nào?"],["Which people lived in North America long before European settlers arrived?",["Indigenous peoples","Astronauts","Ancient Romans","Vikings only"],0,"Indigenous peoples have lived across North America for thousands of years.","Các dân tộc bản địa sống ở Bắc Mỹ từ rất lâu.","Hãy nghĩ đến những cộng đồng đã sống ở Bắc Mỹ từ rất lâu trước người châu Âu."],["Which tool helps show where historical events happened?",["A map","A thermometer","A microscope","A scale"],0,"Maps show locations and how places relate to one another.","Bản đồ giúp xác định địa điểm lịch sử.","Dụng cụ nào thể hiện vị trí các địa điểm trên bề mặt Trái Đất?"],["What are the three branches of the U.S. government?",["Legislative, executive, judicial","Army, navy, air force","City, county, state","Mayor, governor, judge"],0,"Power is divided among Congress (legislative), the President (executive) and the courts (judicial).","Quyền lực chia cho Quốc hội (lập pháp), Tổng thống (hành pháp) và tòa án (tư pháp).","Một nhánh làm luật, một nhánh thi hành luật, một nhánh xét xử."],["Who was the first President of the United States?",["George Washington","Abraham Lincoln","Thomas Jefferson","John Adams"],0,"George Washington became the first U.S. President in 1789.","George Washington là Tổng thống đầu tiên của Mỹ (năm 1789).","Hình ông có trên tờ 1 đô la."],["What is a compass rose on a map?",["A symbol showing directions","A kind of flower","A list of cities","The map title"],0,"A compass rose shows north, south, east and west.","Hoa la bàn chỉ các hướng Bắc, Nam, Đông, Tây trên bản đồ.","Nó giúp ta biết đâu là hướng Bắc."],["What does a map legend (key) explain?",["What the map symbols mean","Who drew the map","How old the map is","The price of the map"],0,"The legend tells what each symbol or color on the map stands for.","Chú giải bản đồ cho biết mỗi ký hiệu hoặc màu sắc có nghĩa là gì.","Nhìn vào ô nhỏ có các ký hiệu ở góc bản đồ."],["Which document is the highest law of the United States?",["The U.S. Constitution","A city map","A school rulebook","A newspaper"],0,"The Constitution sets up the government and is the supreme law of the land.","Hiến pháp lập ra chính phủ và là luật cao nhất của nước Mỹ.","Văn bản này bắt đầu bằng \"We the People\"."],["Why did many people travel west during the Gold Rush?",["To search for gold and wealth","To escape snow","To visit the ocean","To build castles"],0,"News of gold in 1848 drew hundreds of thousands of people hoping to get rich.","Tin tìm thấy vàng năm 1848 thu hút hàng trăm nghìn người mong làm giàu.","Tên của sự kiện đã cho con manh mối."],["What is a natural resource?",["Something from nature people use, like water","A toy made in a factory","A school building","A video game"],0,"Natural resources such as water, soil, trees and minerals come from nature.","Tài nguyên thiên nhiên như nước, đất, cây, khoáng sản đến từ thiên nhiên.","Con người không làm ra nó."],["What is the job of a mayor?",["Lead a city government","Lead the whole country","Judge in the Supreme Court","Command the navy"],0,"A mayor is the elected leader of a city or town.","Thị trưởng là người đứng đầu chính quyền thành phố.","Thống đốc lãnh đạo bang, còn ai lãnh đạo thành phố?"],["What does \"immigrant\" mean?",["A person who moves to a new country to live","A person who never travels","A kind of map","A government building"],0,"An immigrant is someone who comes to live in a new country.","Người nhập cư là người đến sống ở một quốc gia mới.","Nghĩ đến những gia đình chuyển từ nước này sang nước khác."],["Which tool would best show how a town changed over 100 years?",["Old and new photographs","A weather forecast","A grocery list","A calculator"],0,"Comparing old and new photos shows how places change over time.","So sánh ảnh xưa và ảnh nay cho thấy nơi đó thay đổi thế nào.","Con cần thấy được \"trước\" và \"sau\"."],["Which region of the U.S. has the Rocky Mountains?",["The West","The Southeast","New England","The Great Lakes coast"],0,"The Rocky Mountains stretch through the western United States.","Dãy núi Rocky trải dài qua miền Tây nước Mỹ.","Dãy núi này nằm giữa California và vùng đồng bằng lớn."],["Why do communities make rules and laws?",["To keep people safe and treat them fairly","To make games boring","To stop people from learning","To close all parks"],0,"Rules and laws help people stay safe, solve problems, and be treated fairly.","Luật lệ giúp mọi người an toàn, giải quyết mâu thuẫn và được đối xử công bằng.","Thử tưởng tượng đường phố không có đèn giao thông."]],"california":[["Who lived in California long before Spanish missions?",["Indigenous California communities","Gold Rush miners","Railroad engineers","Spanish governors"],0,"Indigenous peoples have lived in California for thousands of years.","Người bản địa đã sống ở California hàng nghìn năm trước khi có các nhà truyền giáo Tây Ban Nha.","Hãy nghĩ về những cộng đồng bản địa trước người châu Âu."],["What is a California mission?",["A Spanish colonial religious settlement","A gold mine","A space station","A state capital"],0,"Spanish missions were religious and colonial institutions.","Mission là cơ sở tôn giáo do Tây Ban Nha lập ra thời thuộc địa.","Các nhà truyền giáo Tây Ban Nha lập cơ sở nào?"],["Which 1848 discovery helped start the California Gold Rush?",["Gold at Sutter's Mill","Oil in Los Angeles","Silver in Nevada","Diamonds in Sacramento"],0,"Gold discovered at Sutter's Mill in 1848 sparked a rush.","Năm 1848 người ta tìm thấy vàng ở Sutter’s Mill, mở đầu Cơn sốt vàng California.","Người ta đổ về California năm 1849 để tìm khoáng sản nào?"],["When did California become a U.S. state?",["1850","1776","1848","1906"],0,"California entered the Union on September 9, 1850.","California trở thành tiểu bang Mỹ ngày 9/9/1850.","Năm California được kết nạp là trước hay sau Cơn sốt vàng 1848?"],["What is California's state capital?",["Sacramento","Los Angeles","San Francisco","San Diego"],0,"Sacramento is the capital of California.","Thủ phủ của California là Sacramento (không phải Los Angeles).","Thủ phủ không nhất thiết là thành phố đông dân nhất."],["What are oral histories?",["Accounts shared through spoken memories","Charts of rainfall","Maps of planets","Lists of multiplication facts"],0,"Oral histories preserve personal and community memories.","Lịch sử truyền miệng là những ký ức được kể lại bằng lời nói.","Lịch sử có thể được lưu lại bằng lời kể không?"],["Which ocean borders California?",["Pacific Ocean","Atlantic Ocean","Indian Ocean","Arctic Ocean"],0,"California's coast faces the Pacific Ocean.","Bờ biển California hướng ra Thái Bình Dương.","California nằm ở bờ Tây hay bờ Đông nước Mỹ?"],["Which landmark spans the Golden Gate strait?",["Golden Gate Bridge","Brooklyn Bridge","London Bridge","Tower Bridge"],0,"The Golden Gate Bridge links San Francisco and Marin County.","Cầu Golden Gate nối San Francisco với hạt Marin.","Cây cầu màu đỏ cam nổi tiếng gần San Francisco tên gì?"],["What happened to many Native Californians during the mission period?",["They faced forced labor and loss of freedom","They all became Spanish officials","They moved to the Moon","They ruled Spain"],0,"The mission system brought coercion, disease, and severe disruption to Indigenous communities.","Hệ thống truyền giáo đã cưỡng ép lao động, mang bệnh tật và làm xáo trộn nặng nề đời sống người bản địa.","Tìm hiểu tác động của hệ thống truyền giáo đối với dân bản địa."],["What helped people travel to California in the 1800s?",["Trails and later railroads","Airplanes","Submarines","Spacecraft"],0,"Overland trails and the transcontinental railroad connected regions.","Người ta đến California bằng các con đường mòn trên bộ, sau đó là đường sắt xuyên lục địa.","Trước khi có máy bay, người dân đi đường bộ bằng gì?"],["What is a historical artifact?",["An object made or used in the past","A weather forecast","A math equation","A fantasy creature"],0,"Artifacts provide evidence about people's lives.","Hiện vật lịch sử là đồ vật được làm ra hoặc sử dụng trong quá khứ, giúp ta hiểu đời sống con người xưa.","Đồ vật cũ có thể kể chuyện về con người trong quá khứ không?"],["Why do historians compare multiple sources?",["To check perspectives and evidence","To make every story identical","To avoid dates","To replace maps with guesses"],0,"Comparing sources helps test claims and recognize different viewpoints.","So sánh nhiều nguồn giúp kiểm tra thông tin và thấy được các góc nhìn khác nhau.","Hai nguồn có thể kể khác nhau về cùng một sự kiện vì sao?"],["Before 1848, California was governed by which country?",["Mexico","Canada","France","Russia"],0,"California was part of Mexico before the U.S. acquired it in 1848.","California thuộc Mexico trước khi Mỹ giành được vùng đất này năm 1848.","Trước khi thuộc Mỹ, California từng thuộc về quốc gia láng giềng ở phía nam nước Mỹ."],["What was a rancho in Mexican-era California?",["A large land grant or cattle ranch","A railroad station","An aircraft factory","A mining spaceship"],0,"Ranchos were large properties that often focused on cattle raising.","Rancho là những vùng đất rộng được cấp thời Mexico, thường dùng để chăn nuôi gia súc.","Thời Mexico, chăn nuôi gia súc trên đất rộng phổ biến như thế nào?"],["Which work involved many Chinese immigrants in 19th-century California?",["Building the transcontinental railroad","Launching Apollo 11","Building ancient pyramids","Designing Roman aqueducts"],0,"Chinese laborers made major contributions to western railroad construction.","Nhiều người Hoa đã góp công lớn xây dựng đường sắt xuyên lục địa.","Trong thế kỷ 19, người Hoa góp công lớn vào công trình giao thông nào?"],["What happened to many Indigenous Californians during the Gold Rush?",["Violence, displacement, and loss of land","They all received new land grants","They immediately became governors","Their communities faced no changes"],0,"The Gold Rush brought severe violence, displacement, and land loss to Native Californians.","Cơn sốt vàng gây ra bạo lực, mất nhà cửa và mất đất đai cho người bản địa California.","Cơn sốt vàng ảnh hưởng thế nào đến đất đai và cộng đồng người bản địa?"]],"space":[["Which planet is the largest in our Solar System?",["Earth","Jupiter","Mars","Venus"],1,"Jupiter is the largest planet in our Solar System.","Sao Mộc là hành tinh lớn nhất trong Hệ Mặt Trời.","Hành tinh khí khổng lồ có Vết Đỏ Lớn."],["How many moons does Earth have?",["One","Two","Four","Zero"],0,"Earth has one natural Moon.","Trái Đất có một vệ tinh tự nhiên là Mặt Trăng.","Đó là vật sáng ta thường thấy trên trời ban đêm."],["Which star is at the center of our Solar System?",["Polaris","The Sun","Sirius","Betelgeuse"],1,"The Sun is the star at the center of the Solar System.","Mặt Trời là ngôi sao ở trung tâm Hệ Mặt Trời.","Ngôi sao này cho Trái Đất phần lớn ánh sáng và hơi ấm."],["A rover collects 6 rocks each day for 4 days. How many rocks?",["10","20","24","28"],2,"6 × 4 = 24 rocks.","6 viên mỗi ngày × 4 ngày = 24 viên.","Bốn nhóm, mỗi nhóm 6."],["What force keeps planets in orbit around the Sun?",["Friction","Gravity","Magnetism alone","Sound"],1,"The Sun’s gravity helps keep planets in orbit.","Lực hấp dẫn của Mặt Trời giữ các hành tinh chuyển động trên quỹ đạo.","Lực hút giữa các vật có khối lượng."],["What is the name of our galaxy?",["Andromeda","The Milky Way","Whirlpool","Triangulum"],1,"Our Solar System is part of the Milky Way galaxy.","Hệ Mặt Trời nằm trong thiên hà Ngân Hà.","Dải sáng mờ vắt ngang bầu trời đêm, tiếng Việt gọi là sông Ngân."],["A spacecraft travels 90 km in 3 hours. Average speed?",["30 km/h","60 km/h","93 km/h","270 km/h"],0,"Average speed = distance ÷ time = 90 ÷ 3 = 30 km/h.","Vận tốc trung bình = quãng đường chia thời gian = 30 km/giờ.","Lấy quãng đường chia thời gian."],["Which planet is closest to the Sun?",["Mercury","Mars","Neptune","Earth"],0,"Mercury orbits closest to the Sun.","Sao Thủy là hành tinh gần Mặt Trời nhất.","Tên hành tinh này giống tên vị thần đưa tin nhanh nhất."],["Which planet is called the Red Planet?",["Mars","Venus","Jupiter","Uranus"],0,"Iron-rich dust makes Mars look red.","Bụi chứa sắt làm Sao Hỏa có màu đỏ.","Tên tiếng Việt của nó có chữ \"Hỏa\" (lửa)."],["About how long does Earth take to orbit the Sun once?",["About 365 days","About 24 hours","About 7 days","About 30 days"],0,"One trip around the Sun takes about 365 days — one year.","Trái Đất quay quanh Mặt Trời một vòng mất khoảng 365 ngày (1 năm).","Đó là độ dài của một năm."],["Why does the Moon shine at night?",["It reflects sunlight","It makes its own fire","It has giant lamps","It glows from ice"],0,"The Moon has no light of its own; it reflects light from the Sun.","Mặt Trăng không tự phát sáng mà phản chiếu ánh sáng Mặt Trời.","Mặt Trăng giống như một tấm gương lớn."],["An astronaut drinks 3 liters of water a day. How much in 7 days?",["21 liters","10 liters","18 liters","24 liters"],0,"3 liters × 7 days = 21 liters.","3 lít × 7 ngày = 21 lít.","Nhân số lít mỗi ngày với số ngày."],["What is a constellation?",["A pattern of stars in the sky","A type of rocket","A moon of Mars","A space suit"],0,"Constellations are star patterns people named, like the Big Dipper.","Chòm sao là nhóm ngôi sao tạo thành hình, ví dụ chòm Bắc Đẩu.","Người xưa nối các ngôi sao thành hình con vật."],["Which planet is the hottest?",["Venus","Mercury","Mars","Saturn"],0,"Venus’s thick carbon-dioxide air traps heat, making it the hottest planet.","Bầu khí quyển dày của Sao Kim giữ nhiệt nên nó nóng nhất.","Không phải hành tinh gần Mặt Trời nhất đâu!"]]},"5":{"math":[["What is 3/5 + 1/5?",["4/10","4/5","3/10","2/5"],1,"Add numerators because denominators are the same.","Mẫu số giống nhau, cộng tử số.","Hai phân số cùng mẫu số thì chỉ cộng phần nào?"],["What is 2.4 × 3?",["5.4","6.2","7.2","72"],2,"24 × 3 = 72, then place one decimal digit.","24×3=72, rồi đặt dấu thập phân.","2,4 là 24 phần mười; nhân với 3 ra bao nhiêu phần mười?"],["A 4 cm by 3 cm by 2 cm prism has what volume?",["9 cm³","12 cm³","24 cm³","36 cm³"],2,"Volume is length × width × height.","Thể tích: dài×rộng×cao = 24.","Hình hộp chữ nhật có ba kích thước; hãy nhân chúng."],["What is 35% of 200?",["35","70","100","65"],1,"0.35 × 200 = 70.","Đổi 35% thành 0.35 rồi nhân 200.","10% của 200 là 20; 35% bằng 3,5 lần 10%."],["What is 6.25 + 1.8?",["8.05","7.05","8.5","6.43"],0,"Line up decimal points: 6.25 + 1.80 = 8.05.","Viết 1,8 thành 1,80 rồi cộng thẳng hàng: 6,25 + 1,80 = 8,05.","Viết 1,8 thành 1,80 và đặt thẳng hàng dấu thập phân."],["What is 7.2 ÷ 3?",["2.4","24","0.24","3.4"],0,"72 tenths divided by three is 24 tenths.","72 phần mười chia 3 được 24 phần mười, tức 2,4.","Chia như số nguyên rồi đặt lại dấu thập phân."],["Which fraction equals 6/8 in simplest form?",["3/4","2/3","4/6","6/4"],0,"Divide numerator and denominator by two.","Chia cả tử và mẫu cho 2: 6/8 = 3/4.","Tìm ước chung của 6 và 8."],["What is 2/3 + 1/6?",["5/6","3/9","1/2","4/6"],0,"2/3 = 4/6, so 4/6 + 1/6 = 5/6.","2/3 = 4/6, nên 4/6 + 1/6 = 5/6.","Quy đồng mẫu số thành 6 trước khi cộng."],["What is the volume of a box 5 × 4 × 3 cm?",["60 cm³","12 cm³","20 cm³","47 cm³"],0,"Volume = length × width × height = 60 cm³.","Thể tích = dài × rộng × cao = 5 × 4 × 3 = 60 cm³.","Thể tích hình hộp chữ nhật là dài × rộng × cao."],["What is 0.7 × 0.6?",["0.42","4.2","0.13","42"],0,"Seven tenths times six tenths equals 42 hundredths.","7 × 6 = 42; có hai chữ số thập phân nên 0,7 × 0,6 = 0,42.","Nhân 7×6 rồi đếm hai chữ số thập phân."],["What is 3/4 of 28?",["21","7","24","18"],0,"28 ÷ 4 × 3 = 21.","28 ÷ 4 = 7, rồi 7 × 3 = 21.","Chia 28 thành bốn phần bằng nhau rồi lấy ba phần."],["What is 5²?",["25","10","7","52"],0,"5 squared means 5 × 5.","5² = 5 × 5 = 25.","Mũ 2 có nghĩa là nhân số đó với chính nó."],["Compute 36 ÷ (2 + 4).",["6","9","18","42"],0,"Evaluate parentheses first: 36 ÷ 6 = 6.","Tính trong ngoặc trước: 2 + 4 = 6, rồi 36 ÷ 6 = 6.","Luôn thực hiện phép tính trong ngoặc trước."],["A rectangle has area 48 cm² and width 6 cm. Its length?",["8 cm","42 cm","24 cm","288 cm"],0,"Length = area ÷ width = 48 ÷ 6.","Chiều dài = diện tích ÷ chiều rộng = 48 ÷ 6 = 8 cm.","Lấy diện tích chia chiều rộng để được chiều dài."],["Which number has the greatest value?",["0.805","0.78","0.8","0.79"],0,"0.805 is greater than 0.800 and the other choices.","So sánh đến hàng phần nghìn: 0,805 > 0,800 > 0,790 > 0,780.","Thêm số 0 để so sánh đến hàng phần nghìn."],["What is 30% of 90?",["27","30","3","60"],0,"0.30 × 90 = 27.","10% của 90 là 9; 30% là 9 × 3 = 27.","10% của 90 là bao nhiêu? Sau đó nhân ba."]],"science":[["A liquid changes to a gas at its surface. What is this?",["Condensation","Evaporation","Freezing","Erosion"],1,"Evaporation is the change from liquid to gas.","Bay hơi là lỏng chuyển thành khí.","Nước ở ngoài trời cũng mất dần dù chưa sôi; đó là quá trình gì?"],["What is a food web?",["A spider home","Connected food chains","A type of plant","A weather chart"],1,"Food webs show many feeding relationships.","Lưới thức ăn gồm nhiều chuỗi thức ăn liên kết.","Nhiều chuỗi thức ăn nối với nhau tạo thành gì?"],["Which force pulls objects toward Earth?",["Friction","Gravity","Magnetism only","Electricity only"],1,"Gravity attracts objects toward Earth.","Trọng lực kéo vật về phía Trái Đất.","Lực nào làm vật rơi xuống đất?"],["Which material is generally a good conductor of electricity?",["Rubber","Plastic","Copper","Dry wood"],2,"Copper allows electric current to flow easily.","Đồng là chất dẫn điện tốt.","Kim loại thường dẫn điện tốt hơn cao su và nhựa."],["Which process helps plants make sugar?",["Photosynthesis","Digestion","Erosion","Condensation"],0,"Plants use light energy to make sugars from water and carbon dioxide.","Quang hợp: cây dùng năng lượng ánh sáng để tạo đường từ nước và khí CO₂.","Lá cây dùng năng lượng từ đâu để tạo chất dinh dưỡng?"],["Where does most fresh water on Earth exist?",["Glaciers and ice sheets","Rivers","The atmosphere","Lakes"],0,"Most of Earth's freshwater is frozen in ice.","Phần lớn nước ngọt trên Trái Đất nằm ở dạng băng (sông băng, băng tảng).","Nước ngọt nằm trong băng hay trong sông nhiều hơn?"],["In a circuit, what must be complete for current to flow?",["A closed path","A broken wire","An open switch","An empty battery"],0,"Current flows in a complete circuit with an energy source.","Dòng điện chỉ chạy khi mạch kín (đường đi liền mạch) và có nguồn điện.","Dòng điện có đi được khi công tắc mở không?"],["Which body system transports oxygen in blood?",["Circulatory system","Skeletal system","Digestive system","Integumentary system"],0,"The heart and blood vessels circulate oxygen-rich blood.","Hệ tuần hoàn (tim và mạch máu) đưa máu giàu oxy đi khắp cơ thể.","Hệ nào có tim và mạch máu?"],["Which adaptation helps a polar bear keep warm?",["Thick fur and fat","Very thin skin","Wide leaves","Transparent scales"],0,"Insulation slows heat loss.","Bộ lông dày và lớp mỡ giúp gấu Bắc Cực giữ ấm, hạn chế mất nhiệt.","Bộ phận nào giúp hạn chế mất nhiệt?"],["What causes most ocean tides?",["Moon's gravity","Earthquakes","Wind alone","Coral reefs"],0,"The Moon's gravity is the strongest driver of tides.","Lực hấp dẫn của Mặt Trăng là nguyên nhân chính gây ra thủy triều.","Hãy nghĩ lực hấp dẫn của thiên thể nào ảnh hưởng thủy triều."],["A plant bends toward a window. This is ...",["Phototropism","Freezing","Condensation","Magnetism"],0,"Phototropism is growth toward light.","Hướng sáng là hiện tượng cây mọc hướng về phía ánh sáng.","Ánh sáng là kích thích làm cây hướng về đâu?"],["What is the role of a decomposer?",["Break down dead organic matter","Make sunlight","Create rocks","Stop all fungi"],0,"Decomposers recycle nutrients from dead material.","Sinh vật phân hủy phân giải xác sinh vật, trả chất dinh dưỡng lại cho đất.","Nấm và vi sinh vật phân hủy xác sinh vật để làm gì?"],["What is a physical change?",["Ice crushing into small pieces","Iron rusting","Wood burning","Baking a cake"],0,"Breaking ice changes its size, not its chemical identity.","Đập nhỏ nước đá chỉ đổi kích thước, không tạo chất mới nên là biến đổi vật lý.","Chất mới có được tạo ra khi chỉ đập nhỏ nước đá?"],["What does the heart do?",["Pumps blood","Filters sunlight","Makes bones","Stores thoughts"],0,"The heart moves blood through the circulatory system.","Tim bơm máu đi khắp cơ thể qua hệ tuần hoàn.","Tim giúp máu di chuyển như thế nào?"],["When the Moon is between Earth and Sun, its visible phase may be ...",["New Moon","Full Moon","Third quarter","First quarter"],0,"A new Moon occurs near alignment with the Moon between Earth and Sun.","Khi Mặt Trăng nằm giữa Trái Đất và Mặt Trời, mặt được chiếu sáng quay đi nên ta thấy trăng non (gần như không thấy).","Pha trăng nào khó nhìn thấy từ Trái Đất?"],["Which is a variable in a fair experiment?",["A factor you can change or measure","Always a constant","Only the conclusion","Only the notebook"],0,"A variable is a factor in an investigation.","Biến số là yếu tố có thể thay đổi hoặc đo được trong thí nghiệm.","Thí nghiệm có thể thay đổi ánh sáng hay nước tưới như thế nào?"]],"history":[["In which year was the U.S. Declaration of Independence adopted?",["1492","1776","1865","1914"],1,"It was adopted on July 4, 1776.","Tuyên ngôn Độc lập Hoa Kỳ được thông qua năm 1776.","Bản tuyên ngôn ra đời trong cuộc cách mạng giành độc lập, ở thế kỷ 18."],["What is the U.S. Constitution?",["A weather map","The supreme law of the country","A treaty of 1492","A school schedule"],1,"It establishes the federal government and foundational rights.","Hiến pháp là luật tối cao và thiết lập chính quyền liên bang.","Đạo luật cao nhất tổ chức bộ máy chính quyền là gì?"],["What was one major reason colonies protested British rule?",["Taxes without representation","Too much snow","Space travel","No railroads"],0,"Colonists objected to taxation without representation in Parliament.","Người dân thuộc địa phản đối thuế khi không có đại diện.","Người dân phản đối bị đánh thuế nhưng không được tham gia quyết định."],["Who was the first U.S. president?",["Thomas Jefferson","George Washington","Abraham Lincoln","James Madison"],1,"George Washington was inaugurated in 1789.","George Washington là tổng thống đầu tiên.","Vị tổng thống đầu tiên lãnh đạo Hoa Kỳ từ năm 1789."],["Which document begins 'We the People'?",["U.S. Constitution","Declaration of Independence","Bill of Rights only","Mayflower Compact"],0,"The U.S. Constitution’s Preamble begins with the words “We the People.”","Hiến pháp Hoa Kỳ mở đầu bằng Lời nói đầu: “We the People…”.","Ba từ mở đầu Hiến pháp Hoa Kỳ là gì?"],["What does the Bill of Rights refer to?",["First ten amendments","First ten presidents","First ten colonies","First ten states"],0,"The Bill of Rights contains the Constitution's first ten amendments.","Bill of Rights (Tuyên ngôn Nhân quyền) là 10 tu chính án đầu tiên của Hiến pháp.","Những sửa đổi đầu tiên nhằm bảo vệ quyền gì?"],["Which branch of U.S. government interprets federal laws?",["Judicial","Legislative","Executive","Military"],0,"Federal courts interpret laws and resolve cases.","Nhánh tư pháp (các tòa án liên bang) giải thích luật và xét xử.","Tòa án thuộc nhánh nào của chính quyền?"],["What is the purpose of checks and balances?",["Limit power among branches","Choose school sports teams","Avoid all elections","Give all power to one person"],0,"Branches can constrain each other to prevent concentration of power.","Kiểm soát và cân bằng giúp các nhánh giám sát lẫn nhau, không để một nhánh nắm quá nhiều quyền.","Các nhánh chính quyền giám sát nhau để tránh điều gì?"],["Who wrote most of the Declaration of Independence draft?",["Thomas Jefferson","George Washington","Benjamin Franklin alone","Alexander Hamilton"],0,"Thomas Jefferson was the principal author of the draft.","Thomas Jefferson là người viết chính bản dự thảo Tuyên ngôn Độc lập.","Ai là người viết phần lớn bản dự thảo?"],["The U.S. Constitution was signed in what year?",["1787","1776","1803","1865"],0,"Delegates signed it at the Constitutional Convention in 1787.","Hiến pháp được ký tại Hội nghị Lập hiến năm 1787.","Sự kiện này diễn ra sau năm 1776 bao lâu?"],["What was the Boston Tea Party?",["A protest against British tea policies","A presidential election","A railroad opening","A celebration of independence in 1865"],0,"Colonists protested British taxation and control in 1773.","Năm 1773, người dân thuộc địa đổ trà xuống cảng Boston để phản đối thuế và sự kiểm soát của Anh.","Người dân thuộc địa đổ trà xuống cảng để phản đối chính sách nào?"],["Which three branches divide federal government powers?",["Legislative, executive, judicial","Military trade media","State city federal","Finance science sports"],0,"The Constitution separates legislative, executive, and judicial powers.","Hiến pháp chia quyền liên bang thành ba nhánh: lập pháp, hành pháp và tư pháp.","Nhớ ba nhánh: làm luật, thi hành luật, xét xử."],["What is a colony?",["A territory governed by another country","An independent planet","A school district","A type of tax"],0,"Colonies are politically controlled from elsewhere.","Thuộc địa là vùng lãnh thổ bị một nước khác cai trị.","Thuộc địa do chính quyền ở đâu kiểm soát?"],["What did the Louisiana Purchase do in 1803?",["Expanded U.S. territory","Ended the Civil War","Founded California","Created the United Nations"],0,"Buying the Louisiana Territory from France roughly doubled the size of the United States.","Vụ mua Louisiana năm 1803 làm lãnh thổ Hoa Kỳ rộng gần gấp đôi.","Việc mua đất làm lãnh thổ Hoa Kỳ thay đổi thế nào?"],["What is one responsibility of Congress?",["Make federal laws","Command state schools directly","Decide every court case","Elect foreign leaders"],0,"Congress is the legislative branch.","Quốc hội là nhánh lập pháp, có nhiệm vụ làm luật liên bang.","Cơ quan lập pháp có nhiệm vụ chính gì?"],["What is federalism?",["Power shared between national and state governments","Power held only by cities","Government without laws","Only one branch of government"],0,"Federalism divides authority across levels of government.","Chế độ liên bang là quyền lực được chia giữa chính quyền trung ương và chính quyền tiểu bang.","Chính quyền liên bang và tiểu bang cùng có quyền hạn không?"]],"space":[["Which planet is the largest in our Solar System?",["Earth","Jupiter","Mars","Venus"],1,"Jupiter is the largest planet in our Solar System.","Sao Mộc là hành tinh lớn nhất trong Hệ Mặt Trời.","Hành tinh khí khổng lồ có Vết Đỏ Lớn."],["How many moons does Earth have?",["One","Two","Four","Zero"],0,"Earth has one natural Moon.","Trái Đất có một vệ tinh tự nhiên là Mặt Trăng.","Đó là vật sáng ta thường thấy trên trời ban đêm."],["Which star is at the center of our Solar System?",["Polaris","The Sun","Sirius","Betelgeuse"],1,"The Sun is the star at the center of the Solar System.","Mặt Trời là ngôi sao ở trung tâm Hệ Mặt Trời.","Ngôi sao này cho Trái Đất phần lớn ánh sáng và hơi ấm."],["A rover collects 6 rocks each day for 4 days. How many rocks?",["10","20","24","28"],2,"6 × 4 = 24 rocks.","6 viên mỗi ngày × 4 ngày = 24 viên.","Bốn nhóm, mỗi nhóm 6."],["What force keeps planets in orbit around the Sun?",["Friction","Gravity","Magnetism alone","Sound"],1,"The Sun’s gravity helps keep planets in orbit.","Lực hấp dẫn của Mặt Trời giữ các hành tinh chuyển động trên quỹ đạo.","Lực hút giữa các vật có khối lượng."],["What is the name of our galaxy?",["Andromeda","The Milky Way","Whirlpool","Triangulum"],1,"Our Solar System is part of the Milky Way galaxy.","Hệ Mặt Trời nằm trong thiên hà Ngân Hà.","Dải sáng mờ vắt ngang bầu trời đêm, tiếng Việt gọi là sông Ngân."],["A spacecraft travels 90 km in 3 hours. Average speed?",["30 km/h","60 km/h","93 km/h","270 km/h"],0,"Average speed = distance ÷ time = 90 ÷ 3 = 30 km/h.","Vận tốc trung bình = quãng đường chia thời gian = 30 km/giờ.","Lấy quãng đường chia thời gian."],["Which planet is closest to the Sun?",["Mercury","Mars","Neptune","Earth"],0,"Mercury orbits closest to the Sun.","Sao Thủy là hành tinh gần Mặt Trời nhất.","Tên hành tinh này giống tên vị thần đưa tin nhanh nhất."],["Which planet is called the Red Planet?",["Mars","Venus","Jupiter","Uranus"],0,"Iron-rich dust makes Mars look red.","Bụi chứa sắt làm Sao Hỏa có màu đỏ.","Tên tiếng Việt của nó có chữ \"Hỏa\" (lửa)."],["About how long does Earth take to orbit the Sun once?",["About 365 days","About 24 hours","About 7 days","About 30 days"],0,"One trip around the Sun takes about 365 days — one year.","Trái Đất quay quanh Mặt Trời một vòng mất khoảng 365 ngày (1 năm).","Đó là độ dài của một năm."],["Why does the Moon shine at night?",["It reflects sunlight","It makes its own fire","It has giant lamps","It glows from ice"],0,"The Moon has no light of its own; it reflects light from the Sun.","Mặt Trăng không tự phát sáng mà phản chiếu ánh sáng Mặt Trời.","Mặt Trăng giống như một tấm gương lớn."],["An astronaut drinks 3 liters of water a day. How much in 7 days?",["21 liters","10 liters","18 liters","24 liters"],0,"3 liters × 7 days = 21 liters.","3 lít × 7 ngày = 21 lít.","Nhân số lít mỗi ngày với số ngày."],["What is a constellation?",["A pattern of stars in the sky","A type of rocket","A moon of Mars","A space suit"],0,"Constellations are star patterns people named, like the Big Dipper.","Chòm sao là nhóm ngôi sao tạo thành hình, ví dụ chòm Bắc Đẩu.","Người xưa nối các ngôi sao thành hình con vật."],["Which planet is the hottest?",["Venus","Mercury","Mars","Saturn"],0,"Venus’s thick carbon-dioxide air traps heat, making it the hottest planet.","Bầu khí quyển dày của Sao Kim giữ nhiệt nên nó nóng nhất.","Không phải hành tinh gần Mặt Trời nhất đâu!"]]},"6":{"math":[["What is 3/4 ÷ 1/2?",["3/8","3/2","1/4","2/3"],1,"Multiply by the reciprocal: 3/4 × 2 = 3/2.","Chia cho một phân số bằng cách nhân với phân số nghịch đảo của số chia.","Chia cho 1/2 có nghĩa là có bao nhiêu nửa trong 3/4?"],["What is 20% of 85?",["15","17","20","25"],1,"0.20 × 85 = 17.","Đổi 20% thành 0.2 rồi nhân 85.","10% của 85 bằng 8,5; hãy nhân đôi."],["Solve: x + 9 = 23.",["12","13","14","15"],2,"Subtract 9 from both sides: x = 14.","Trừ 9 ở cả hai vế.","Để tìm x, loại 9 ra khỏi vế có x."],["A ratio is 2:3. If the first quantity is 10, what is the second?",["6","12","15","20"],2,"Multiply both parts of 2:3 by five, giving 10:15.","Tỷ lệ 2:3 nhân 5 thành 10:15.","Để từ 2 thành 10, hai vế của tỷ số cùng nhân bao nhiêu?"],["Calculate −7 + 12.",["5","−19","19","−5"],0,"Moving twelve units right from −7 lands at 5.","Từ −7 đi sang phải 12 đơn vị trên trục số thì đến 5.","Trên trục số, đi từ −7 sang phải 12 đơn vị."],["Compute 2/3 × 3/4.",["1/2","5/7","6/7","2"],0,"Multiply tops and bottoms, then simplify 6/12 to 1/2.","Nhân tử với tử, mẫu với mẫu: 6/12, rút gọn còn 1/2.","Nhân tử với tử và mẫu với mẫu, rồi rút gọn."],["Compute 5/6 − 1/3.",["1/2","4/3","2/3","4/6"],0,"One third is 2/6, so 5/6 − 2/6 = 3/6.","1/3 = 2/6, nên 5/6 − 2/6 = 3/6 = 1/2.","Đổi 1/3 thành phân số có mẫu số 6."],["Which ratio is equivalent to 4:7?",["12:21","8:11","16:21","7:4"],0,"Multiply both ratio terms by three to get 12:21.","Nhân cả hai số của 4:7 với 3 được 12:21.","Nhân cả hai số trong tỷ số với cùng một số."],["Solve 4x + 3 = 27.",["6","8","7","5"],0,"Subtract 3, then divide by 4.","Trừ 3 hai vế: 4x = 24, chia 4: x = 6.","Trừ 3 ở hai vế rồi chia cả hai vế cho 4."],["What is the mean of 4, 8, 10, 14?",["9","10","8","36"],0,"The total is 36; divide by four values to get 9.","Tổng là 4 + 8 + 10 + 14 = 36; chia 4 được trung bình 9.","Cộng bốn số rồi chia cho số lượng các số."],["What is 3/5 as a percent?",["60%","30%","35%","80%"],0,"3 ÷ 5 = 0.6, or 60%.","3 ÷ 5 = 0,6 = 60%.","Viết phân số thành số thập phân rồi đổi sang phần trăm."],["A triangle has base 10 cm and height 8 cm. Area?",["40 cm²","80 cm²","18 cm²","36 cm²"],0,"Triangle area = 1/2 × base × height = 40.","Diện tích tam giác = đáy × cao ÷ 2 = 10 × 8 ÷ 2 = 40 cm².","Diện tích tam giác bằng đáy nhân chiều cao chia hai."],["What is 2.5 × 0.4?",["1","10","0.1","0.9"],0,"25 × 4 = 100, with two decimal places gives 1.00.","25 × 4 = 100; có hai chữ số thập phân nên được 1,00 = 1.","Nhân như số nguyên rồi đếm chữ số sau dấu thập phân."],["How far apart are −5 and 3 on a number line?",["8","2","−8","5"],0,"Distance = 3 − (−5) = 8 units.","Khoảng cách = 3 − (−5) = 8 đơn vị.","Đếm số bước trên trục số từ −5 đến 3."],["The ratio of boys to girls is 3:4. If 12 boys, how many girls?",["16","9","15","18"],0,"Three parts equal twelve, so each part is four; four parts is sixteen.","3 phần ứng với 12 bạn trai nên 1 phần = 4; bạn gái 4 phần = 16.","Tìm một phần bằng 12÷3, rồi nhân 4."],["Which inequality means 'at most 9'?",["x ≤ 9","x ≥ 9","x > 9","x = 10"],0,"At most includes all values less than or equal to nine.","“Nhiều nhất là 9” gồm cả số 9 và các số nhỏ hơn: x ≤ 9.","'Không quá 9' có bao gồm số 9 không?"]],"science":[["Which organelle releases energy from food in most eukaryotic cells?",["Nucleus","Mitochondrion","Cell wall","Ribosome"],1,"Mitochondria help produce ATP using energy from food.","Ti thể giúp tế bào tạo năng lượng ATP.","Bào quan nào thường được ví như nhà máy năng lượng của tế bào?"],["Which Earth layer is liquid?",["Inner core","Outer core","Crust","Lower mantle"],1,"The outer core is mainly liquid iron and nickel.","Lõi ngoài chủ yếu gồm sắt và niken ở trạng thái lỏng.","Phân biệt lõi trong rắn với lớp kim loại lỏng bao quanh nó."],["What happens to particles as temperature usually rises?",["They move faster","They vanish","They stop moving","They become larger atoms"],0,"Higher temperature means greater average particle motion.","Nhiệt độ tăng thường làm chuyển động nhiệt trung bình của các hạt mạnh hơn.","Khi nóng hơn, chuyển động hạt thường mạnh lên hay yếu đi?"],["What describes an ecosystem?",["Only animals","Organisms and their environment","Only plants","A single rock"],1,"Ecosystems include living things and nonliving surroundings.","Hệ sinh thái gồm sinh vật và môi trường sống.","Hệ sinh thái gồm cả sinh vật và những yếu tố không sống nào?"],["What is the smallest unit of an element retaining its identity?",["Atom","Tissue","Planet","Organ"],0,"An atom is the basic unit of an element.","Nguyên tử là đơn vị nhỏ nhất của một nguyên tố mà vẫn giữ tính chất của nguyên tố đó.","Nguyên tố được cấu tạo từ hạt cơ bản nào?"],["What is density?",["Mass per unit volume","Volume per unit time","Speed per unit mass","Temperature per unit area"],0,"Density = mass ÷ volume.","Khối lượng riêng (mật độ) = khối lượng ÷ thể tích.","Để tính khối lượng riêng cần biết khối lượng và đại lượng nào?"],["Which process breaks rocks without moving them?",["Weathering","Erosion","Condensation","Photosynthesis"],0,"Weathering breaks down rock in place.","Phong hóa làm đá vỡ vụn ngay tại chỗ, không di chuyển đi.","Phong hóa làm đá vỡ tại chỗ hay mang chúng đi?"],["Which is an abiotic factor?",["Temperature","Grass","Fungi","Insects"],0,"Abiotic means nonliving environmental factors.","Yếu tố vô sinh là yếu tố không sống, như nhiệt độ.","Yếu tố vô sinh có sống hay không?"],["What type of energy does a moving skateboard have?",["Kinetic energy","Chemical potential only","Nuclear energy","Sound energy only"],0,"Moving objects have kinetic energy.","Vật đang chuyển động có động năng.","Động năng gắn với vật đứng yên hay chuyển động?"],["What is the role of the nucleus in a eukaryotic cell?",["Stores most genetic material","Produces all sunlight","Digests all food","Forms Earth's crust"],0,"The nucleus houses most of the cell's DNA.","Nhân tế bào chứa phần lớn DNA (vật chất di truyền) của tế bào.","Bộ phận nào là nơi lưu trữ phần lớn DNA?"],["When water freezes, its molecules generally ...",["Move less and form an ordered structure","Disappear","Become different elements","Stop all motion"],0,"Cooling reduces average molecular motion.","Khi nước đông đặc, các phân tử chuyển động chậm lại và xếp thành cấu trúc trật tự.","Nhiệt độ giảm thì chuyển động các phân tử thay đổi ra sao?"],["What is an independent variable?",["Factor changed by the experimenter","Final conclusion","Measurement recorded","A fixed control"],0,"The independent variable is intentionally manipulated.","Biến độc lập là yếu tố người làm thí nghiệm chủ động thay đổi.","Yếu tố nào được người làm thí nghiệm chủ động thay đổi?"],["What is the major source of Earth's surface energy?",["Sun","Inner core only","Moon","Earthquakes"],0,"Sunlight is the dominant energy input to ecosystems and weather.","Mặt Trời là nguồn năng lượng chính cho bề mặt Trái Đất, thời tiết và hệ sinh thái.","Nguồn sáng và nhiệt chính trên bề mặt Trái Đất đến từ đâu?"],["What is the function of producers in a food chain?",["Make organic food from energy","Eat only predators","Decompose all rocks","Never use sunlight"],0,"Producers build organic molecules using light or chemical energy.","Sinh vật sản xuất (như cây xanh) tự tạo chất hữu cơ từ năng lượng ánh sáng hoặc hóa học.","Sinh vật sản xuất tạo thức ăn hay chỉ ăn sinh vật khác?"],["Which property describes resistance to flow?",["Viscosity","Density","Volume","Solubility"],0,"Viscosity is a fluid's resistance to flow.","Độ nhớt là tính cản trở sự chảy của chất lỏng (mật ong nhớt hơn nước).","Mật ong chảy chậm hơn nước vì tính chất nào?"],["Which plate boundary often creates mid-ocean ridges?",["Divergent","Convergent","Transform only","No plate boundary"],0,"Plates pull apart at divergent boundaries.","Ở ranh giới tách giãn, các mảng tách xa nhau và tạo ra sống núi giữa đại dương.","Các mảng kiến tạo đang tách ra hay va vào nhau?"]],"history":[["Which early civilization developed along the Nile River?",["Maya","Ancient Egypt","Inca","Phoenicia"],1,"Egyptian civilization developed along the Nile.","Ai Cập cổ đại phát triển dọc sông Nile.","Con sông nổi tiếng của Ai Cập cổ đại là sông nào?"],["What was a key purpose of the Silk Roads?",["Space research","Exchange of goods and ideas","Building pyramids","Flying airplanes"],1,"Trade routes connected regions and spread ideas.","Con đường Tơ lụa trao đổi hàng hóa và ý tưởng.","Con đường buôn bán nối các vùng Á-Âu giúp trao đổi hàng hóa và điều gì khác?"],["Which empire was centered on Rome?",["Roman Empire","Mali Empire","Aztec Empire","Mongol Empire"],0,"Rome was the center of the Roman Empire.","Đế chế La Mã lấy thành Rome làm trung tâm.","Thành Rome là trung tâm một đế chế cổ đại."],["What did early farming allow many communities to do?",["Always travel","Build permanent settlements","Invent satellites","Stop using water"],1,"Farming supported settled communities and food surpluses.","Nông nghiệp giúp hình thành cộng đồng định cư.","Canh tác có giúp con người sống cố định ở một nơi không?"],["What writing system is associated with ancient Mesopotamia?",["Cuneiform","Hieroglyphs only","Braille","Morse code"],0,"Cuneiform was used in ancient Mesopotamia.","Chữ hình nêm (cuneiform) được dùng ở Lưỡng Hà cổ đại.","Chữ viết hình nêm xuất hiện ở vùng Lưỡng Hà."],["Which river supported ancient Chinese civilizations?",["Yellow River","Nile","Amazon","Danube"],0,"Early Chinese states developed around the Yellow River basin.","Các nhà nước Trung Hoa đầu tiên hình thành quanh lưu vực sông Hoàng Hà.","Sông Hoàng Hà nằm ở nền văn minh nào?"],["What was a city-state?",["An independent city with surrounding territory","A city with no government","A modern U.S. state","Only a farming tool"],0,"City-states were self-governing political communities.","Thành bang là một thành phố tự cai quản cùng vùng đất xung quanh.","Thành bang có chính quyền riêng không?"],["Which civilization developed the concept of democracy in Athens?",["Ancient Greeks","Ancient Incas","Ancient Egyptians","Vikings"],0,"Athens in ancient Greece practiced forms of direct democracy.","Người Hy Lạp cổ ở Athens thực hiện hình thức dân chủ trực tiếp.","Athens thuộc nền văn minh cổ đại nào?"],["What is an empire?",["A state controlling multiple territories or peoples","A single village always","Only a religious building","A seasonal festival"],0,"Empires exercise authority over broad territories and peoples.","Đế chế là nhà nước cai trị nhiều vùng lãnh thổ hoặc nhiều dân tộc.","Đế chế thường cai trị chỉ một làng hay nhiều vùng?"],["What was the Code of Hammurabi?",["A collection of Babylonian laws","A Roman road","An Egyptian tomb","A Chinese compass"],0,"It was an early written law code from ancient Babylon.","Bộ luật Hammurabi là bộ luật thành văn sớm của Babylon.","Những quy tắc được khắc thành văn bản để làm gì?"],["Why was the Nile flooding important to ancient Egypt?",["It deposited fertile silt","It prevented all farming","It created desert sand","It stopped trade"],0,"Annual floods often enriched farmland with silt.","Lũ sông Nile hằng năm bồi đắp phù sa, làm đất trồng màu mỡ.","Phù sa giúp đất trồng trọt màu mỡ ra sao?"],["Which religion began in ancient India?",["Buddhism","Christianity","Islam","Judaism"],0,"Buddhism arose in the Indian subcontinent.","Đạo Phật ra đời ở tiểu lục địa Ấn Độ.","Đạo Phật khởi nguồn ở khu vực châu Á nào?"],["What was one contribution of ancient Romans?",["Aqueduct engineering","The first moon rocket","The internet","The printing press"],0,"Roman aqueducts transported water across distances.","Người La Mã xây cầu dẫn nước (aqueduct) để đưa nước đi xa.","Cầu dẫn nước của La Mã dùng để vận chuyển gì?"],["Which civilization built Machu Picchu?",["Inca","Aztec","Maya","Ancient Greek"],0,"The Inca built Machu Picchu in the Andes.","Người Inca xây Machu Picchu trên dãy Andes.","Thành đá trên núi Andes thuộc nền văn minh nào?"],["What were the great pyramids of Giza built as?",["Tombs for pharaohs","Grain markets","Army forts","Libraries"],0,"The pyramids were monumental tombs built for Egyptian pharaohs.","Kim tự tháp là lăng mộ khổng lồ dành cho các pharaoh Ai Cập.","Người Ai Cập cổ tin vào cuộc sống sau khi chết."],["What is archaeology?",["Study of past human life through material remains","Prediction of hurricanes","Study of stars only","Analysis of computer code"],0,"Archaeologists use objects and sites to learn about people.","Khảo cổ học nghiên cứu đời sống con người xưa qua đồ vật và di tích để lại.","Nhà khảo cổ nghiên cứu đồ vật, di tích để biết điều gì?"]],"space":[["Which planet is famous for its prominent rings?",["Mercury","Saturn","Venus","Mars"],1,"Saturn has a striking system of rings made largely of ice particles.","Sao Thổ nổi tiếng với các vành đai gồm nhiều hạt băng.","Hành tinh thứ sáu tính từ Mặt Trời."],["A probe transmits 125 images daily for 4 days. Total?",["500","129","400","625"],0,"125 × 4 = 500 images.","125 hình/ngày × 4 ngày = 500 hình.","Nhân số ảnh mỗi ngày với số ngày."],["Why do astronauts appear weightless in orbit?",["There is no gravity","They are in continuous free fall","Air pressure cancels gravity","Space removes mass"],1,"Orbiting astronauts and their spacecraft are in continuous free fall.","Phi hành gia và tàu vũ trụ cùng rơi tự do khi bay theo quỹ đạo.","Trên quỹ đạo vẫn có lực hấp dẫn."],["What force keeps planets in orbit around the Sun?",["Friction","Gravity","Magnetism alone","Sound"],1,"The Sun’s gravity helps keep planets in orbit.","Lực hấp dẫn của Mặt Trời giữ các hành tinh chuyển động trên quỹ đạo.","Lực hút giữa các vật có khối lượng."],["What is the name of our galaxy?",["Andromeda","The Milky Way","Whirlpool","Triangulum"],1,"Our Solar System is part of the Milky Way galaxy.","Hệ Mặt Trời nằm trong thiên hà Ngân Hà.","Dải sáng mờ vắt ngang bầu trời đêm, tiếng Việt gọi là sông Ngân."],["A spacecraft travels 90 km in 3 hours. Average speed?",["30 km/h","60 km/h","93 km/h","270 km/h"],0,"Average speed = distance ÷ time = 90 ÷ 3 = 30 km/h.","Vận tốc trung bình = quãng đường chia thời gian = 30 km/giờ.","Lấy quãng đường chia thời gian."],["What causes the phases of the Moon?",["Earth’s shadow each night","Our viewing angle of the sunlit Moon","Clouds around the Moon","The Moon changing shape"],1,"We see different fractions of the Moon’s illuminated side during its orbit.","Ta thấy những phần được Mặt Trời chiếu sáng khác nhau của Mặt Trăng.","Mặt Trăng không hề thay đổi hình dạng thật."],["A rocket uses 3/4 of 120 fuel units. How many units?",["30","60","90","100"],2,"Three fourths of 120 = 120 × 3 ÷ 4 = 90.","Ba phần tư của 120 bằng 90.","Tìm 1/4 trước, rồi nhân 3."],["What is a light-year?",["Time to orbit the Sun","A unit of distance","Speed of sound","Length of a calendar year"],1,"A light-year measures the distance light travels in one year.","Năm ánh sáng là đơn vị đo khoảng cách, không phải thời gian.","Tên có chữ “năm” nhưng nó không đo thời gian."],["A spacecraft travels 3.5 × 10⁴ km. How far is that?",["350 km","3,500 km","35,000 km","350,000 km"],2,"10⁴ = 10,000; 3.5 × 10,000 = 35,000 km.","10⁴ = 10.000, nên 3,5 × 10.000 = 35.000 km.","Dời dấu phẩy sang phải 4 chữ số."],["The main asteroid belt lies between which two planets?",["Mars and Jupiter","Earth and Mars","Venus and Earth","Saturn and Uranus"],0,"Most asteroids orbit in a belt between Mars and Jupiter.","Phần lớn tiểu hành tinh nằm trong vành đai giữa Sao Hỏa và Sao Mộc.","Nó nằm giữa hành tinh đất đá cuối cùng và hành tinh khí đầu tiên."],["Why can’t sound travel through outer space?",["There is almost no air to carry it","Space is too cold","Stars block it","It moves too fast"],0,"Sound needs a medium such as air; space is nearly a vacuum.","Âm thanh cần môi trường như không khí; vũ trụ gần như chân không.","Âm thanh cần các hạt để rung."],["A satellite orbits Earth every 90 minutes. How many orbits in 6 hours?",["4","6","3","9"],0,"6 hours = 360 minutes; 360 ÷ 90 = 4 orbits.","6 giờ = 360 phút; 360 ÷ 90 = 4 vòng.","Đổi giờ sang phút trước."],["Which is classified as a dwarf planet?",["Pluto","Mars","Jupiter","Venus"],0,"Pluto was reclassified as a dwarf planet in 2006.","Năm 2006, Sao Diêm Vương được xếp lại thành hành tinh lùn.","Nó từng là \"hành tinh thứ 9\"."]]},"7":{"math":[["What is −8 + 13?",["−21","−5","5","21"],2,"Move 13 steps right from −8 to 5.","−8 cộng 13 bằng 5.","Từ −8 trên trục số, đi sang phải 13 đơn vị."],["Solve: 3x = 24.",["6","7","8","9"],2,"Divide both sides by 3.","Chia hai vế cho 3.","Muốn tìm x trong 3x, hãy chia hai vế cho 3."],["A $60 item is 25% off. What is its sale price?",["$15","$35","$40","$45"],3,"The discount is $15, so the final price is $45.","Giảm 15 đô nên còn 45 đô.","Giảm 25% nghĩa là còn trả bao nhiêu phần trăm giá gốc?"],["What is the probability of rolling a 6 on a fair six-sided die?",["1/2","1/3","1/6","1/12"],2,"There is one favorable result out of six equally likely results.","Có 1 trong 6 mặt là số 6.","Xúc xắc có 6 mặt ngang cơ hội; mấy mặt ghi số 6?"],["Solve 2x − 5 = 17.",["11","6","12","22"],0,"Add 5 and divide by 2 to get 11.","Cộng 5 hai vế: 2x = 22, chia 2: x = 11.","Cộng 5 ở hai vế rồi chia 2."],["What is −4 × −6?",["24","−24","−10","10"],0,"A negative times a negative is positive, and 4×6=24.","Âm nhân âm ra dương, 4 × 6 = 24.","Hai số âm nhân nhau cho kết quả dấu gì?"],["Find 15% of 80.",["12","8","15","20"],0,"10% is 8 and 5% is 4, totaling 12.","10% của 80 là 8, 5% là 4; cộng lại 12.","Tính 10% rồi thêm 5% của 80."],["Simplify 5a + 2a − 3a.",["4a","10a","7a","0a"],0,"Combine coefficients: 5+2−3 = 4.","Cộng trừ hệ số: 5 + 2 − 3 = 4, được 4a.","Cộng và trừ hệ số của các hạng tử cùng biến."],["A map scale is 1 cm to 5 km. What is 7 cm?",["35 km","12 km","7 km","25 km"],0,"Multiply 7 by 5 km per centimeter.","7 cm × 5 km/cm = 35 km.","Mỗi cm ứng với 5 km, vậy 7 cm gấp mấy lần?"],["A circle has diameter 14 cm. What is its radius?",["7 cm","28 cm","14 cm","49 cm"],0,"Radius is half the diameter.","Bán kính bằng nửa đường kính: 14 ÷ 2 = 7 cm.","Bán kính bằng nửa đường kính."],["What is 2³ × 2²?",["32","64","16","12"],0,"Add exponents with the same base: 2⁵ = 32.","Cùng cơ số thì cộng số mũ: 2³ × 2² = 2⁵ = 32.","Nhân lũy thừa cùng cơ số thì cộng số mũ."],["A bag has 3 red and 5 blue marbles. Probability of red?",["3/8","3/5","5/8","1/3"],0,"There are eight marbles total and three are red.","Có 8 viên bi, 3 viên đỏ nên xác suất là 3/8.","Đếm tổng số viên rồi đếm số viên đỏ."],["An $80 shirt increases in price by 10%. New price?",["$88","$72","$90","$8"],0,"10% of $80 is $8; add it to the original price.","10% của 80 đô là 8 đô; giá mới 80 + 8 = 88 đô.","Tăng giá là cộng thêm, không phải trừ đi."],["A rectangle's length is 3 times its width. Width 5 m. Perimeter?",["40 m","20 m","30 m","75 m"],0,"Length is 15 m; perimeter = 2(15+5)=40 m.","Chiều dài 15 m; chu vi = 2 × (15 + 5) = 40 m.","Tìm chiều dài trước rồi cộng bốn cạnh."],["Find the constant of proportionality: y=6x.",["6","x","1/6","0"],0,"In y=kx, the constant is k=6.","Trong y = kx, hằng số tỷ lệ là k = 6.","So sánh biểu thức y=kx và tìm hệ số k."],["What is the mean of 6, 7, 11?",["8","9","7","24"],0,"Sum 24 divided by three is 8.","Tổng 6 + 7 + 11 = 24; chia 3 được 8.","Trung bình cộng bằng tổng chia số phần tử."]],"science":[["What is the main role of chlorophyll in plants?",["Store bones","Absorb light for photosynthesis","Move roots","Make soil"],1,"Chlorophyll absorbs light energy used in photosynthesis.","Diệp lục hấp thụ năng lượng ánh sáng cho quá trình quang hợp.","Sắc tố màu xanh trong lá cây hấp thụ loại năng lượng nào?"],["Which is evidence of a chemical reaction?",["Ice melting","Paper folding","Gas forming from mixed substances","Salt dissolving"],2,"New gas formation can indicate new substances.","Khí mới sinh ra có thể là dấu hiệu phản ứng hóa học.","Khí mới sinh ra khi trộn chất có thể báo hiệu có chất mới."],["An object travels 120 meters in 20 seconds. What is its average speed?",["4 m/s","6 m/s","8 m/s","12 m/s"],1,"Speed = distance ÷ time = 120 ÷ 20 = 6 m/s.","Tốc độ trung bình bằng quãng đường chia cho thời gian.","Tốc độ bằng quãng đường chia thời gian."],["What drives the water cycle?",["Sun energy and gravity","Moonlight only","Earthquakes only","Ocean salt alone"],0,"Sunlight drives evaporation; gravity brings water down.","Năng lượng Mặt Trời và trọng lực vận hành vòng tuần hoàn nước.","Mặt Trời cung cấp năng lượng, trọng lực đưa nước về mặt đất."],["Which cell part controls entry and exit of materials?",["Cell membrane","Cell wall only","Nucleolus","Chromosome"],0,"A cell membrane regulates passage of substances.","Màng tế bào kiểm soát các chất ra vào tế bào.","Lớp bao quanh tế bào giúp kiểm soát chất ra vào là gì?"],["What is the reactant in photosynthesis besides water?",["Carbon dioxide","Oxygen","Glucose","Chlorophyll"],0,"Photosynthesis uses carbon dioxide and water to produce sugar.","Quang hợp dùng CO₂ và nước để tạo đường.","Cây hấp thụ khí nào từ không khí khi quang hợp?"],["What happens in cellular respiration?",["Energy in food is transferred to ATP","Sunlight is made","Atoms disappear","Only water evaporates"],0,"Cells release usable energy from food molecules.","Hô hấp tế bào giải phóng năng lượng từ thức ăn và chuyển vào ATP.","Hô hấp tế bào giúp chuyển năng lượng của thức ăn thành gì?"],["Which is a genotype?",["Bb","Brown eyes","Tall height","Purple petals"],0,"A genotype is an allele combination such as Bb.","Kiểu gen là tổ hợp alen, ví dụ Bb; còn “mắt nâu” là kiểu hình.","Kiểu gen được biểu diễn bằng cặp chữ cái hay đặc điểm nhìn thấy?"],["Which force opposes sliding motion?",["Friction","Gravity only","Buoyancy","Magnetism only"],0,"Friction resists relative motion of surfaces.","Lực ma sát cản trở chuyển động trượt giữa hai bề mặt.","Vì sao xe đang lăn chậm lại khi phanh?"],["What does a balanced force produce?",["No change in velocity","Guaranteed acceleration","An explosion","Mass loss"],0,"Zero net force means no acceleration.","Lực cân bằng (hợp lực bằng 0) thì vận tốc không thay đổi.","Khi hợp lực bằng 0, vận tốc có bắt buộc thay đổi không?"],["What is the SI unit of force?",["Newton","Joule","Watt","Pascal"],0,"Force is measured in newtons (N).","Đơn vị SI của lực là newton (N).","Đơn vị này mang tên nhà khoa học người Anh nổi tiếng với câu chuyện quả táo rơi."],["What type of rock forms from cooled magma?",["Igneous","Sedimentary","Metamorphic","Fossil"],0,"Igneous rocks solidify from molten rock.","Đá mácma (igneous) hình thành khi đá nóng chảy nguội đi và đông đặc.","Dung nham nguội và đông đặc tạo đá gì?"],["Which particle has negative electric charge?",["Electron","Proton","Neutron","Alpha particle"],0,"Electrons have negative charge.","Electron mang điện tích âm.","Trong ba hạt electron, proton, neutron, hạt nào mang điện âm?"],["Which is a pure element?",["Copper (Cu)","Salt water","Air","Granite"],0,"Copper is made of one type of atom.","Đồng (Cu) chỉ gồm một loại nguyên tử nên là nguyên tố tinh khiết.","Nguyên tố chỉ chứa một loại nguyên tử."],["Why do we see different seasons?",["Earth's tilt as it orbits the Sun","Earth is closer to Sun only","Moon phases","Ocean tides"],0,"Earth's axial tilt changes sunlight angle and day length.","Trục Trái Đất nghiêng nên góc chiếu nắng và độ dài ngày thay đổi trong năm, tạo ra các mùa.","Trục Trái Đất nghiêng ảnh hưởng góc chiếu sáng thế nào?"],["Which is a chemical change?",["Iron rusting","Ice breaking","Water boiling","Sugar dissolving"],0,"Rusting forms new iron oxide compounds.","Sắt gỉ tạo ra chất mới (oxit sắt) nên là biến đổi hóa học.","Biến đổi nào tạo chất mới?"]],"history":[["What was a major feature of medieval feudalism in Europe?",["Land-based obligations","Mass air travel","Digital money","Universal voting"],0,"Land and obligations linked lords and vassals.","Chế độ phong kiến gắn với đất đai và nghĩa vụ.","Đất đai và nghĩa vụ giữa lãnh chúa, chư hầu là nền tảng của chế độ nào?"],["Why was the printing press important?",["It stopped learning","It spread written ideas more widely","It invented electricity","It ended farming"],1,"Printing helped books and ideas reach more people.","Máy in giúp sách và tri thức phổ biến hơn.","Công nghệ nào giúp sản xuất nhiều sách cùng nội dung nhanh hơn?"],["The Renaissance began in which European region?",["Scandinavia","Italian city-states","Iceland","Siberia"],1,"Renaissance culture grew strongly in Italian cities.","Phong trào Phục Hưng khởi phát mạnh ở các đô thị Ý.","Phong trào Phục hưng khởi đầu ở các thành bang của một bán đảo châu Âu."],["What did the Magna Carta of 1215 help establish?",["Limits on royal power","Universal internet","A Roman emperor","An Egyptian dynasty"],0,"It helped establish a tradition that rulers are subject to law.","Đại Hiến chương góp phần hạn chế quyền lực nhà vua.","Văn kiện Magna Carta đặt giới hạn đối với quyền lực của nhà vua."],["What was the Black Death?",["A plague pandemic in medieval Eurasia","An ancient Greek election","A Roman road","The first space mission"],0,"Plague devastated many communities in the 1300s.","Cái Chết Đen là đại dịch dịch hạch tàn phá Âu–Á vào thế kỷ 14 (những năm 1300).","Đại dịch xảy ra ở Âu-Á vào thế kỷ 14 là gì?"],["Who was Johannes Gutenberg?",["A pioneer of movable-type printing in Europe","A pharaoh","A Roman emperor","An Inca leader"],0,"His printing methods expanded book production in Europe.","Gutenberg là người tiên phong in bằng chữ rời ở châu Âu, giúp sách được in nhiều hơn.","Công nghệ in sách giúp tri thức lan rộng."],["What was the Protestant Reformation?",["A religious movement challenging Catholic institutions","An ocean exploration route","A Roman law code","An industrial machine"],0,"The Reformation transformed European religious life.","Cải cách Tin Lành là phong trào tôn giáo thách thức Giáo hội Công giáo, làm thay đổi đời sống tôn giáo châu Âu.","Phong trào cải cách tôn giáo diễn ra ở châu lục nào?"],["Which explorer's voyages linked Europe to the Americas in 1492?",["Christopher Columbus","Marco Polo","Ferdinand Magellan only","Zheng He"],0,"Columbus's voyages began lasting transatlantic contact and colonization.","Năm 1492, Columbus đi thuyền đến châu Mỹ, mở đầu sự tiếp xúc lâu dài giữa châu Âu và châu Mỹ.","Năm 1492 là chuyến đi của nhà hàng hải nào?"],["What was a major consequence of European colonization in the Americas?",["Severe harm to Indigenous populations","No cultural change","End of all world trade","Instant equality for everyone"],0,"Disease, dispossession, and violence harmed many Indigenous peoples.","Bệnh dịch, bị chiếm đất và bạo lực đã gây tổn hại nặng nề cho người bản địa châu Mỹ.","Cần xem cả tác động đối với cộng đồng bản địa."],["The Mali Empire became known for trade in ...",["Gold and salt","Silicon chips","Oil and cars","Tea and rubber"],0,"Trans-Saharan trade connected gold and salt markets.","Đế quốc Mali giàu lên nhờ buôn vàng và muối qua sa mạc Sahara.","Qua sa mạc Sahara, người ta trao đổi những hàng hóa nào?"],["Which civilization built large temples at Angkor?",["Khmer Empire","Roman Empire","Inca Empire","Aztec Empire"],0,"The Khmer Empire built Angkor temples in Southeast Asia.","Đế quốc Khmer xây các đền Angkor ở Campuchia ngày nay.","Đền Angkor nằm ở Campuchia ngày nay."],["Which empire continued the Roman tradition from Constantinople after the West fell?",["Byzantine Empire","Mongol Empire","Aztec Empire","Mali Empire"],0,"The Eastern Roman (Byzantine) Empire lasted until 1453 with its capital at Constantinople.","Đế quốc Đông La Mã (Byzantine) tồn tại đến năm 1453, kinh đô là Constantinople.","Đây là nửa phía đông của Đế quốc La Mã."],["Why were medieval trade cities important?",["They connected markets and crafts","They stopped all communication","They banned learning","They avoided farming completely"],0,"Cities facilitated exchange and specialized production.","Thành phố buôn bán thời trung cổ là nơi gặp gỡ của thương nhân và thợ thủ công.","Thành phố là điểm gặp của thương nhân và thợ thủ công."],["What was the Age of Exploration?",["Expansion of long-distance ocean voyages","Invention of airplanes","A moon mission","End of all empires"],0,"European voyages expanded global trade and colonization.","Thời đại Khám phá là giai đoạn các chuyến đi biển đường dài mở rộng thương mại và thuộc địa.","Các chuyến đi xa bằng đường biển giúp các đế quốc làm gì?"],["What does a historian mean by continuity?",["Something that persisted over time","A sudden revolution","A prediction","A measurement of speed"],0,"Continuity identifies aspects that remain relatively unchanged.","“Sự liên tục” là những điều vẫn giữ nguyên qua thời gian.","Đặc điểm nào vẫn tiếp tục qua nhiều thời kỳ?"],["What is a secondary historical source?",["A modern scholar's analysis of past events","An original letter","A coin from the era","An eyewitness diary"],0,"Secondary sources interpret primary evidence.","Nguồn thứ cấp là tài liệu do người sau phân tích lại tư liệu gốc, ví dụ bài viết của học giả hiện đại.","Tài liệu phân tích lại tư liệu gốc có phải nguồn thứ cấp không?"]],"space":[["Which planet is famous for its prominent rings?",["Mercury","Saturn","Venus","Mars"],1,"Saturn has a striking system of rings made largely of ice particles.","Sao Thổ nổi tiếng với các vành đai gồm nhiều hạt băng.","Hành tinh thứ sáu tính từ Mặt Trời."],["A probe transmits 125 images daily for 4 days. Total?",["500","129","400","625"],0,"125 × 4 = 500 images.","125 hình/ngày × 4 ngày = 500 hình.","Nhân số ảnh mỗi ngày với số ngày."],["Why do astronauts appear weightless in orbit?",["There is no gravity","They are in continuous free fall","Air pressure cancels gravity","Space removes mass"],1,"Orbiting astronauts and their spacecraft are in continuous free fall.","Phi hành gia và tàu vũ trụ cùng rơi tự do khi bay theo quỹ đạo.","Trên quỹ đạo vẫn có lực hấp dẫn."],["What force keeps planets in orbit around the Sun?",["Friction","Gravity","Magnetism alone","Sound"],1,"The Sun’s gravity helps keep planets in orbit.","Lực hấp dẫn của Mặt Trời giữ các hành tinh chuyển động trên quỹ đạo.","Lực hút giữa các vật có khối lượng."],["What is the name of our galaxy?",["Andromeda","The Milky Way","Whirlpool","Triangulum"],1,"Our Solar System is part of the Milky Way galaxy.","Hệ Mặt Trời nằm trong thiên hà Ngân Hà.","Dải sáng mờ vắt ngang bầu trời đêm, tiếng Việt gọi là sông Ngân."],["A spacecraft travels 90 km in 3 hours. Average speed?",["30 km/h","60 km/h","93 km/h","270 km/h"],0,"Average speed = distance ÷ time = 90 ÷ 3 = 30 km/h.","Vận tốc trung bình = quãng đường chia thời gian = 30 km/giờ.","Lấy quãng đường chia thời gian."],["What causes the phases of the Moon?",["Earth’s shadow each night","Our viewing angle of the sunlit Moon","Clouds around the Moon","The Moon changing shape"],1,"We see different fractions of the Moon’s illuminated side during its orbit.","Ta thấy những phần được Mặt Trời chiếu sáng khác nhau của Mặt Trăng.","Mặt Trăng không hề thay đổi hình dạng thật."],["A rocket uses 3/4 of 120 fuel units. How many units?",["30","60","90","100"],2,"Three fourths of 120 = 120 × 3 ÷ 4 = 90.","Ba phần tư của 120 bằng 90.","Tìm 1/4 trước, rồi nhân 3."],["What is a light-year?",["Time to orbit the Sun","A unit of distance","Speed of sound","Length of a calendar year"],1,"A light-year measures the distance light travels in one year.","Năm ánh sáng là đơn vị đo khoảng cách, không phải thời gian.","Tên có chữ “năm” nhưng nó không đo thời gian."],["A spacecraft travels 3.5 × 10⁴ km. How far is that?",["350 km","3,500 km","35,000 km","350,000 km"],2,"10⁴ = 10,000; 3.5 × 10,000 = 35,000 km.","10⁴ = 10.000, nên 3,5 × 10.000 = 35.000 km.","Dời dấu phẩy sang phải 4 chữ số."],["The main asteroid belt lies between which two planets?",["Mars and Jupiter","Earth and Mars","Venus and Earth","Saturn and Uranus"],0,"Most asteroids orbit in a belt between Mars and Jupiter.","Phần lớn tiểu hành tinh nằm trong vành đai giữa Sao Hỏa và Sao Mộc.","Nó nằm giữa hành tinh đất đá cuối cùng và hành tinh khí đầu tiên."],["Why can’t sound travel through outer space?",["There is almost no air to carry it","Space is too cold","Stars block it","It moves too fast"],0,"Sound needs a medium such as air; space is nearly a vacuum.","Âm thanh cần môi trường như không khí; vũ trụ gần như chân không.","Âm thanh cần các hạt để rung."],["A satellite orbits Earth every 90 minutes. How many orbits in 6 hours?",["4","6","3","9"],0,"6 hours = 360 minutes; 360 ÷ 90 = 4 orbits.","6 giờ = 360 phút; 360 ÷ 90 = 4 vòng.","Đổi giờ sang phút trước."],["Which is classified as a dwarf planet?",["Pluto","Mars","Jupiter","Venus"],0,"Pluto was reclassified as a dwarf planet in 2006.","Năm 2006, Sao Diêm Vương được xếp lại thành hành tinh lùn.","Nó từng là \"hành tinh thứ 9\"."]]},"8":{"math":[["Solve: 2x + 7 = 21.",["6","7","8","14"],1,"Subtract 7, then divide by 2: x = 7.","Trừ 7 rồi chia 2.","Trừ 7 ở hai vế của phương trình 2x+7=21."],["What is √144?",["11","12","13","14"],1,"12 × 12 = 144.","12 bình phương bằng 144.","Số nào nhân với chính nó bằng 144?"],["Which point lies on y = 2x + 1?",["(1,1)","(2,5)","(0,2)","(3,5)"],1,"If x = 2, then y = 5.","Thay x=2 ta được y=5.","Thế hoành độ x của từng điểm vào y=2x+1 để kiểm tra tung độ."],["What is the slope through (0,2) and (3,8)?",["1","2","3","6"],1,"Slope = (8−2)/(3−0) = 2.","Hệ số góc bằng độ tăng y chia độ tăng x.","Hệ số góc là hiệu hai tung độ chia cho hiệu hai hoành độ."],["Solve 5x − 4 = 2x + 11.",["5","3","7","15"],0,"Subtract 2x; add 4; 3x=15, so x=5.","Trừ 2x hai vế: 3x − 4 = 11; cộng 4: 3x = 15; x = 5.","Chuyển các hạng tử chứa x về cùng một vế."],["What is √169?",["13","14","12","±13"],0,"The principal square root of 169 is 13.","Căn bậc hai (không âm) của 169 là 13.","Tìm số không âm có bình phương bằng 169."],["What is 2⁻³?",["1/8","−8","8","−1/8"],0,"A negative exponent means the reciprocal: 1/2³.","Số mũ âm là nghịch đảo: 2⁻³ = 1/2³ = 1/8.","Số mũ âm nghĩa là lấy nghịch đảo."],["What is the slope through (0,2) and (3,11)?",["3","9","1/3","4"],0,"Slope = (11−2)/(3−0) = 9/3=3.","Hệ số góc = (11 − 2) ÷ (3 − 0) = 9 ÷ 3 = 3.","Lấy hiệu tung độ chia hiệu hoành độ."],["For y=−2x+7, what is y when x=4?",["−1","1","15","−8"],0,"Substitute 4: −2×4+7=−1.","Thay x = 4: −2 × 4 + 7 = −1.","Thay x=4 vào biểu thức rồi tính đúng thứ tự."],["A right triangle has legs 5 and 12. Hypotenuse?",["13","17","10","√119"],0,"By Pythagoras, c² =25+144=169, so c=13.","Pythagoras: 5² + 12² = 25 + 144 = 169, cạnh huyền = 13.","Cạnh huyền thỏa mãn bình phương bằng tổng bình phương hai cạnh góc vuông."],["Write 4.2 × 10³ in standard form.",["4,200","420","42,000","0.0042"],0,"Multiplying by 1000 shifts the decimal three places right.","Nhân với 10³ = 1.000 thì dời dấu phẩy sang phải 3 chữ số: 4.200.","Nhân 10³ thì dời dấu thập phân bao nhiêu chữ số?"],["Solve the system: x+y=10, x−y=4. Find x.",["7","3","6","14"],0,"Add the equations: 2x =14, so x=7.","Cộng hai phương trình: 2x = 14, nên x = 7.","Cộng hai phương trình để khử y."],["What is 15% of 240?",["36","24","48","15"],0,"0.15×240=36.","10% của 240 là 24, 5% là 12; cộng lại 36.","10% của 240 là 24, thêm 5% là bao nhiêu?"],["Which translation moves (−2,5) right 4 units?",["(2,5)","(−6,5)","(−2,9)","(2,9)"],0,"Add four to x; keep y unchanged.","Dịch sang phải 4 đơn vị: cộng 4 vào x, giữ nguyên y: (2, 5).","Dịch sang phải nghĩa là cộng vào tọa độ x."],["Two angles of a triangle are 35° and 65°. Third angle?",["80°","100°","90°","70°"],0,"Interior angles add to 180°: 180−35−65=80.","Tổng ba góc là 180°: 180 − 35 − 65 = 80°.","Tổng ba góc tam giác là 180 độ."],["Simplify (3²)³.",["3⁶","3⁵","3⁹","9³⁻¹"],0,"For a power raised to a power, multiply the exponents.","Lũy thừa của lũy thừa thì nhân số mũ: (3²)³ = 3⁶.","Lũy thừa của lũy thừa thì nhân hai số mũ."]],"science":[["What is the unit of force in the SI system?",["Watt","Newton","Joule","Volt"],1,"Force is measured in newtons (N).","Đơn vị lực là newton (N).","Đơn vị này mang tên nhà khoa học người Anh nổi tiếng với câu chuyện quả táo rơi."],["In a closed system, mass during a chemical reaction is...",["conserved","lost as heat","increased whenever gas forms","decreased whenever heat is released"],0,"Mass is conserved in ordinary chemical reactions.","Khối lượng được bảo toàn trong phản ứng hóa học thông thường.","Trong hệ kín, tổng khối lượng của các chất trước và sau phản ứng có đổi không?"],["Which is an example of kinetic energy?",["A moving bicycle","A raised book at rest","Energy stored in a battery","A stretched spring"],0,"Kinetic energy is energy of motion.","Động năng là năng lượng của chuyển động.","Động năng là năng lượng của vật khi đứng yên hay đang chuyển động?"],["How does natural selection work?",["Heritable traits affecting reproduction can become more common","All traits become equally common","Only acquired traits are inherited","Genetic variation is eliminated in one generation"],0,"Inherited differences can affect survival and reproduction.","Biến dị di truyền có thể ảnh hưởng sống sót và sinh sản.","Những tính trạng truyền cho đời con phải có cơ sở di truyền."],["What is the relationship F=ma called?",["Newton's second law","Boyle's law","Ohm's law","Kepler's third law"],0,"Net force equals mass times acceleration.","F = ma là định luật II Newton: hợp lực bằng khối lượng nhân gia tốc.","Lực, khối lượng và gia tốc liên hệ trong định luật nào?"],["What is potential energy?",["Stored energy due to position or condition","Energy transferred only as heat","Energy that depends only on speed","Energy created by friction alone"],0,"Potential energy can be stored gravitationally or elastically.","Thế năng là năng lượng dự trữ do vị trí (độ cao) hoặc trạng thái (lò xo bị nén).","Vật đặt trên cao có loại năng lượng dự trữ nào?"],["What is the unit of electric current?",["Ampere","Volt","Ohm","Watt"],0,"Electric current is measured in amperes.","Cường độ dòng điện đo bằng ampe (A).","Ampe dùng để đo dòng điện hay hiệu điện thế?"],["What is an atom's nucleus made of?",["Protons and neutrons","Protons and electrons","Neutrons and electrons","Only protons"],0,"Most nuclei contain protons and neutrons.","Hạt nhân nguyên tử gồm proton và neutron.","Những hạt nào nằm ở tâm nguyên tử?"],["What is a chemical compound?",["Substance of chemically bonded different elements","A blend with no chemical bonds","A mixture of two gases","A single type of atom"],0,"Compounds consist of two or more elements chemically bonded.","Hợp chất gồm hai hay nhiều nguyên tố khác nhau liên kết hóa học với nhau.","Hợp chất khác hỗn hợp như thế nào?"],["Which structure carries hereditary instructions?",["DNA","RNA alone in all organisms","A cell wall","Proteins alone without nucleic acids"],0,"DNA encodes inheritable biological information.","DNA mang thông tin di truyền.","Thông tin di truyền nằm ở phân tử nào?"],["What is a genotype ratio in Bb × Bb?",["1 BB : 2 Bb : 1 bb","3 BB : 1 bb","4 Bb only","2 BB : 2 bb"],0,"A Punnett square gives 1:2:1 genotypes.","Bảng Punnett cho Bb × Bb ra tỷ lệ kiểu gen 1 BB : 2 Bb : 1 bb.","Lập bảng Punnett hai hàng hai cột."],["How is speed calculated?",["Distance ÷ time","Time ÷ distance","Force × mass","Volume ÷ mass"],0,"Average speed equals total distance divided by time.","Tốc độ = quãng đường ÷ thời gian.","Đi được quãng đường dài trong thời gian ngắn thì tốc độ thế nào?"],["Why do planets stay in orbit?",["Gravity together with motion","They have zero velocity","Only outward centrifugal force acts","Their paths are held by solar wind"],0,"Gravity bends their paths while they move forward.","Lực hấp dẫn kéo hành tinh vào trong, còn chuyển động tới trước giữ nó không rơi vào Mặt Trời, nên nó đi theo quỹ đạo.","Lực hút giữ hành tinh chuyển động quanh Mặt Trời."],["What is a wave's frequency?",["Cycles per second","Distance per hour","Mass per volume","Pressure per force"],0,"Frequency measures oscillations each second.","Tần số là số dao động trong một giây (đơn vị hertz).","Đếm số dao động trong một giây."],["Which pH is acidic at 25°C?",["pH 3","pH 7","pH 9","pH 12"],0,"Acidic solutions have pH below 7 at 25°C.","Ở 25°C, dung dịch có pH nhỏ hơn 7 là axit, nên pH 3 có tính axit.","pH nhỏ hơn 7 thường biểu thị môi trường gì?"],["What kind of wave is a sound wave in air?",["Longitudinal wave","Transverse light wave","Radio wave","Gamma wave"],0,"In air, sound travels as a longitudinal wave of compressions and rarefactions.","Trong không khí, âm thanh là sóng dọc gồm các vùng nén và giãn.","Các phân tử không khí dao động cùng phương với hướng truyền sóng."]],"history":[["In which year did the U.S. Civil War begin?",["1861","1850","1860","1865"],0,"The Civil War began in 1861.","Nội chiến Hoa Kỳ bắt đầu năm 1861.","Nội chiến diễn ra vào thế kỷ 19; hãy tìm năm đầu thập niên 1860."],["Which amendment abolished slavery in the United States?",["13th","12th","14th","15th"],0,"The 13th Amendment abolished slavery, with limited constitutional exceptions.","Tu chính án 13 bãi bỏ chế độ nô lệ, có ngoại lệ hiến định hạn chế.","Tu chính án nào bãi bỏ chế độ nô lệ sau Nội chiến?"],["What was Reconstruction after the U.S. Civil War?",["Rebuilding and political change in the South","The colonial war for independence","The U.S. entry into World War I","The building of western railroads only"],0,"Reconstruction addressed the postwar South and formerly enslaved people’s rights.","Thời kỳ Tái thiết giải quyết hậu quả Nội chiến và quyền công dân.","Sau chiến tranh, miền Nam Hoa Kỳ trải qua giai đoạn tái thiết."],["What was a major cause of the American Revolution?",["Colonial objections to British policies","Disputes over western land after 1865","Conflicts about the Missouri Compromise","Opposition to the Treaty of Versailles"],0,"Disputes over taxation and self-government fueled revolution.","Tranh chấp về thuế và quyền tự quản dẫn tới cách mạng.","Người dân thuộc địa bất đồng về thuế và quyền tự quản."],["What did abolitionists work to end?",["Slavery","The electoral college","British rule over the colonies","Reconstruction governments"],0,"Abolitionists advocated ending slavery.","Những người theo chủ nghĩa bãi nô đấu tranh xóa bỏ chế độ nô lệ.","Phong trào bãi nô phản đối chế độ nào?"],["What was the Underground Railroad?",["A network helping enslaved people escape","A railway built to transport cotton","A federal railroad linking North and South","A wartime military supply line"],0,"People and networks helped freedom seekers escape enslavement.","“Đường sắt ngầm” là mạng lưới bí mật giúp người nô lệ trốn thoát, không phải tàu thật.","'Đường sắt' ở đây là mạng lưới bí mật hay tàu thật?"],["Why did the North and South disagree before the Civil War?",["Slavery and its expansion","Differences over tariff policy alone","Disputes over a proposed League of Nations","Conflicts caused only by canal construction"],0,"Slavery was central to sectional political conflicts.","Chế độ nô lệ và việc mở rộng nó là mâu thuẫn chính giữa miền Bắc và miền Nam.","Vấn đề cốt lõi gây chia rẽ giữa các tiểu bang là gì?"],["Who issued the Emancipation Proclamation?",["Abraham Lincoln","George Washington","Thomas Jefferson","Ulysses Grant"],0,"Lincoln issued it in 1863 during the Civil War.","Tổng thống Lincoln ban hành Tuyên bố Giải phóng Nô lệ năm 1863 trong Nội chiến.","Vị tổng thống nào lãnh đạo Hoa Kỳ trong Nội chiến?"],["What was the Fourteenth Amendment about?",["Citizenship and equal protection","The process of electing senators directly","Prohibition of alcohol","The expansion of voting rights to women"],0,"It guarantees citizenship and equal protection under law.","Tu chính án 14 bảo đảm quyền công dân và sự bảo vệ bình đẳng trước pháp luật.","Tu chính án này nói về quyền công dân và sự bình đẳng nào?"],["What did the Fifteenth Amendment prohibit?",["Voting discrimination based on race for men","Discrimination in voting based on gender","Poll taxes in all states in 1870","Restrictions on voting based solely on age"],0,"It barred denying the vote based on race, color, or previous servitude.","Tu chính án 15 cấm tước quyền bầu cử vì chủng tộc, màu da hay từng là nô lệ (lúc đó chỉ áp dụng cho nam giới).","Quyền bầu cử bị cấm phân biệt dựa vào yếu tố nào?"],["The transcontinental railroad was completed in what year?",["1869","1850","1865","1889"],0,"Rail lines met at Promontory Summit in 1869.","Đường sắt xuyên lục địa hoàn thành năm 1869 tại Promontory Summit (Utah).","Đường sắt xuyên lục địa hoàn thành sau Nội chiến vài năm."],["What did westward expansion often cause for Native Americans?",["Land loss and displacement","Full recognition of every tribal land treaty","Voluntary resettlement of every tribe","Immediate equal political representation"],0,"Expansion often dispossessed Indigenous peoples.","Việc mở rộng về phía Tây thường khiến người bản địa mất đất và phải rời bỏ quê hương.","Người bản địa mất đất khi người định cư mở rộng về phía Tây."],["What was the Seneca Falls Convention of 1848?",["A women's rights meeting","A convention to ratify the Constitution","A meeting to organize Reconstruction","A convention to debate westward annexation"],0,"It helped launch organized women's rights advocacy in the U.S.","Hội nghị Seneca Falls năm 1848 mở đầu phong trào đấu tranh có tổ chức cho quyền phụ nữ ở Mỹ.","Hội nghị này thảo luận quyền lợi của nhóm nào?"],["What was an industrial factory system?",["Centralized production using machines and workers","Independent craft production in homes","Work organized only through farming cooperatives","Trade managed solely by colonial merchants"],0,"Factories concentrated labor and machinery.","Hệ thống nhà máy là sản xuất tập trung, dùng máy móc và nhiều công nhân ở một nơi.","Máy móc và công nhân tập trung ở đâu để sản xuất?"],["What is the purpose of a historical thesis?",["Make an evidence-based argument","Present an untested opinion","List dates without interpreting them","Describe sources without making a claim"],0,"A thesis states an arguable interpretation supported by evidence.","Luận điểm lịch sử là một lập luận có thể tranh luận và được chứng minh bằng bằng chứng.","Lập luận lịch sử cần chứng cứ hay chỉ ý kiến?"],["What was a key goal of Reconstruction amendments?",["Extend freedom and civil rights","Expand property qualifications for voting","Reinstate the system of indentured servitude","Reduce citizenship protections"],0,"The 13th–15th Amendments reshaped U.S. citizenship and rights.","Các tu chính án 13–15 mở rộng tự do và quyền công dân sau Nội chiến.","Ba tu chính án sau Nội chiến nói về tự do và quyền công dân."]],"space":[["A spacecraft travels 3.5 × 10⁴ km. How far is that?",["350 km","3,500 km","35,000 km","350,000 km"],2,"10⁴ = 10,000; 3.5 × 10,000 = 35,000 km.","10⁴ = 10.000, nên 3,5 × 10.000 = 35.000 km.","Dời dấu phẩy sang phải 4 chữ số."],["If an object’s mass is 5 kg, its weight near Earth is about...",["5 N","49 N","500 N","0.5 N"],1,"Weight = mass × g ≈ 5 × 9.8 = 49 newtons.","Trọng lượng xấp xỉ 5 × 9,8 = 49 N.","Nhân khối lượng với gia tốc trọng trường (≈ 9,8 m/s²)."],["What makes a comet’s tail generally point away from the Sun?",["Solar radiation and solar wind","Earth’s gravity","The comet’s engines","Moonlight"],0,"Solar radiation and solar wind push dust and ion tails away from the Sun.","Ánh sáng và gió Mặt Trời đẩy các đuôi sao chổi ra xa Mặt Trời.","Thứ gì liên tục thổi ra từ Mặt Trời?"],["What causes the phases of the Moon?",["Earth’s shadow each night","Our viewing angle of the sunlit Moon","Clouds around the Moon","The Moon changing shape"],1,"We see different fractions of the Moon’s illuminated side during its orbit.","Ta thấy những phần được Mặt Trời chiếu sáng khác nhau của Mặt Trăng.","Mặt Trăng không hề thay đổi hình dạng thật."],["A rocket uses 3/4 of 120 fuel units. How many units?",["30","60","90","100"],2,"Three fourths of 120 = 120 × 3 ÷ 4 = 90.","Ba phần tư của 120 bằng 90.","Tìm 1/4 trước, rồi nhân 3."],["What is a light-year?",["Time to orbit the Sun","A unit of distance","Speed of sound","Length of a calendar year"],1,"A light-year measures the distance light travels in one year.","Năm ánh sáng là đơn vị đo khoảng cách, không phải thời gian.","Tên có chữ “năm” nhưng nó không đo thời gian."],["The speed of light is about...",["3 × 10⁵ m/s","3 × 10⁸ m/s","3 × 10¹¹ m/s","3 × 10² m/s"],1,"Light travels at about 3.0 × 10⁸ meters per second in vacuum.","Ánh sáng truyền trong chân không khoảng 3 × 10⁸ m/giây.","Số 3 có 8 chữ số 0 phía sau (mét/giây)."],["A 1,200 kg spacecraft accelerates at 2 m/s². Net force?",["600 N","1,202 N","2,400 N","24,000 N"],2,"Newton’s second law: F = ma = 1,200 × 2 = 2,400 N.","Định luật II Newton: F = m × a = 2.400 N.","Nhân khối lượng với gia tốc."],["Which telescope mainly detects radio waves?",["Radio telescope","Optical refractor","Thermal camera only","Microscope"],0,"Radio telescopes receive radio-frequency electromagnetic radiation.","Kính thiên văn vô tuyến thu bức xạ điện từ ở dải sóng vô tuyến.","Nghĩ đến những chảo ăng-ten khổng lồ."],["For a satellite in uniform circular orbit, centripetal acceleration points...",["Tangent to the path","Away from the center","Toward the orbit center","Opposite its velocity always"],2,"Centripetal acceleration always points toward the center of circular motion.","Gia tốc hướng tâm luôn hướng vào tâm quỹ đạo tròn.","“Hướng tâm” nghĩa là hướng về đâu?"],["If F = 750 N acts on 250 kg, what is acceleration?",["0.33 m/s²","3 m/s²","500 m/s²","1,000 m/s²"],1,"Using F = ma gives a = F/m = 750/250 = 3 m/s².","Từ F = ma suy ra a = 750/250 = 3 m/s².","Biến đổi F = ma để tìm a."],["What does a redshift in light from a distant galaxy often indicate?",["It is approaching us","It is receding from us","It stopped emitting light","It has no stars"],1,"Cosmological redshift is associated with expansion and recession.","Dịch chuyển đỏ của thiên hà xa thường liên quan đến sự giãn nở của vũ trụ.","Bước sóng ánh sáng ta nhận được bị kéo dài ra."],["Which element makes up most of the Sun?",["Hydrogen","Iron","Oxygen","Carbon"],0,"About three-quarters of the Sun’s mass is hydrogen.","Khoảng 3/4 khối lượng Mặt Trời là hydro.","Đây là nguyên tố nhẹ nhất."],["What process powers the Sun?",["Nuclear fusion","Burning coal","Nuclear fission of uranium","Static electricity"],0,"In the core, hydrogen nuclei fuse into helium and release energy.","Trong lõi, hạt nhân hydro hợp nhất thành heli và giải phóng năng lượng.","Các hạt nhân nhỏ kết hợp lại thành hạt nhân lớn hơn."],["What is escape velocity?",["Minimum speed to break free of a body’s gravity","Top speed of a car","Speed of sound in space","Speed of a falling leaf"],0,"Escape velocity is the minimum launch speed needed to leave a body’s gravity without more thrust (about 11.2 km/s for Earth).","Vận tốc thoát ly là tốc độ tối thiểu để thoát khỏi lực hấp dẫn (khoảng 11,2 km/s với Trái Đất).","Tên gọi có chữ \"escape\" — thoát ra."]]},"9":{"math":[["Solve: 5x − 7 = 18.",["3","4","5","6"],2,"Add 7, then divide by 5: x = 5.","Cộng 7 rồi chia 5.","Thêm 7 vào hai vế của 5x−7=18 rồi chia cho 5."],["Factor x² − 9.",["(x−9)(x+1)","(x−3)(x+3)","(x−1)(x+9)","(x−3)²"],1,"This is a difference of squares: a²−b²=(a−b)(a+b).","Hiệu hai bình phương: (x−3)(x+3).","Hiệu hai bình phương là (a−b)(a+b)."],["If f(x) = 2x², what is f(3)?",["6","12","18","36"],2,"2 × 3² = 2 × 9 = 18.","Thay x=3: 2×9=18.","Thay x=3 vào 2x², bình phương trước khi nhân."],["What is the hypotenuse of a right triangle with legs 6 and 8?",["10","12","14","16"],0,"By Pythagoras, c²=6²+8²=100.","Định lý Pythagoras cho cạnh huyền 10.","Áp dụng định lý Pythagoras: 6²+8²."],["Solve 3(x−4)=21.",["11","9","7","17"],0,"Divide by 3, then add 4 to get x=11.","Chia hai vế cho 3: x − 4 = 7, cộng 4: x = 11.","Chia hai vế cho 3 rồi cộng 4."],["Factor x² + 7x + 12.",["(x+3)(x+4)","(x+2)(x+6)","(x−3)(x−4)","(x+1)(x+12)"],0,"Three and four multiply to twelve and add to seven.","3 và 4 có tích 12 và tổng 7, nên x² + 7x + 12 = (x + 3)(x + 4).","Tìm hai số có tích 12 và tổng 7."],["Solve x² = 49 for real x.",["x=±7","x=7 only","x=49","x=±49"],0,"Both 7 and −7 square to 49.","Cả 7 và −7 bình phương đều bằng 49, nên x = ±7.","Hai số đối nhau có thể cùng bình phương ra 49 không?"],["Find slope of y = −3x + 8.",["−3","8","3","−8"],0,"Slope-intercept form is y=mx+b; m=−3.","Trong dạng y = mx + b, hệ số góc là m = −3.","Trong dạng y=mx+b, hệ số nào là độ dốc?"],["If f(x)=x²−2x, find f(−3).",["15","3","−15","9"],0,"(−3)²−2(−3)=9+6=15.","(−3)² − 2 × (−3) = 9 + 6 = 15.","Khi thay số âm, nhớ đặt trong ngoặc để tính bình phương."],["What is (x³)(x⁴)?",["x⁷","x¹²","x","2x⁷"],0,"Add exponents with the same base.","Cùng cơ số thì cộng số mũ: x³ × x⁴ = x⁷.","Hai lũy thừa cùng cơ số nhân nhau thì cộng số mũ."],["A line passes (2,3) and (6,11). What is its slope?",["2","1/2","4","8"],0,"Slope = (11−3)/(6−2)=8/4=2.","Hệ số góc = (11 − 3) ÷ (6 − 2) = 8 ÷ 4 = 2.","Hiệu tung độ chia hiệu hoành độ."],["Solve the system x+y=9 and x−y=1. Find y.",["4","5","8","1"],0,"Adding equations gives x=5; then y=4.","Cộng hai phương trình: 2x = 10, x = 5; thế vào: y = 9 − 5 = 4.","Cộng hai phương trình để tìm x, sau đó thế lại."],["What is the vertex of y=(x+1)²−4?",["(−1,−4)","(1,−4)","(−1,4)","(4,−1)"],0,"Vertex form y=(x−h)²+k gives h=−1,k=−4.","Dạng đỉnh y = (x − h)² + k; ở đây h = −1, k = −4, đỉnh (−1, −4).","Trong ngoặc x+1 nghĩa là đỉnh có hoành độ nào?"],["A right triangle has legs 9 and 12. Hypotenuse?",["15","21","√63","13"],0,"The square root of 9²+12² is 15.","Pythagoras: 9² + 12² = 81 + 144 = 225, căn bậc hai là 15.","Dùng định lý Pythagoras."],["Which is a solution of 2x+1 < 9?",["x=3","x=4","x=5","x=6"],0,"2x <8 means x<4, so 3 works.","2x + 1 < 9 ⇒ 2x < 8 ⇒ x < 4, nên x = 3 thỏa mãn.","Giải bất phương trình rồi thử các đáp án."],["Factor 4x²−25.",["(2x−5)(2x+5)","(4x−5)(x+5)","(2x−5)²","(4x−25)(x+1)"],0,"A difference of squares: (2x)²−5².","Hiệu hai bình phương: (2x)² − 5² = (2x − 5)(2x + 5).","Nhận ra hiệu hai bình phương."]],"science":[["What is the atomic number of an element?",["Number of protons","Number of protons plus neutrons","Number of valence electrons only","Average mass of its isotopes"],0,"Atomic number equals the number of protons in the nucleus.","Số hiệu nguyên tử bằng số proton trong hạt nhân.","Số hiệu nguyên tử bằng số hạt dương trong hạt nhân."],["What is the main function of DNA?",["Store genetic information","Catalyze every reaction in a cell","Store energy directly as ATP","Form the cell membrane"],0,"DNA stores hereditary information.","DNA lưu trữ thông tin di truyền.","Phân tử nào chứa thông tin di truyền?"],["A 10 N net force acts on a 2 kg object. What is acceleration?",["2 m/s²","5 m/s²","10 m/s²","20 m/s²"],1,"F = ma, so a = 10/2 = 5 m/s².","Định luật II Newton: a=F/m.","Dùng F=ma để tìm a=F÷m."],["What is the pH of a neutral solution at about 25°C?",["0","3","7","14"],2,"Pure water is approximately pH 7 at 25°C.","Nước trung tính có pH khoảng 7 ở 25°C.","Môi trường trung tính có pH ở giữa thang 0–14 khi khoảng 25°C."],["What does an element's atomic mass mostly reflect?",["Protons and neutrons","Number of outer-shell electrons only","Total charge of nucleus","Molecular bonds to neighbors"],0,"Almost all atomic mass comes from protons and neutrons.","Khối lượng nguyên tử chủ yếu đến từ proton và neutron trong hạt nhân.","Khối lượng nguyên tử tập trung ở hạt nào trong hạt nhân?"],["Which particle has positive charge?",["Proton","Electron","Neutron","Photon"],0,"Protons carry positive charge.","Đáp án đúng: Proton. Proton và electron có dấu điện tích trái nhau.","Hạt này nằm trong hạt nhân và quyết định số hiệu nguyên tử."],["What is an isotope?",["Atoms of same element with different neutrons","Atoms with the same neutrons but different proton counts","Atoms differing only in electron count","Molecules of the same two elements"],0,"Isotopes share proton count but differ in neutron number.","Đồng vị là các nguyên tử cùng số proton nhưng khác số neutron.","Đồng vị cùng số proton nhưng khác số hạt nào?"],["Which bond involves electron sharing?",["Covalent","Ionic","Metallic only","Hydrogen bond only"],0,"Covalent bonds involve shared electron pairs.","Liên kết cộng hóa trị là khi các nguyên tử dùng chung cặp electron.","Khi nguyên tử cùng dùng chung electron, đó là liên kết gì?"],["What is kinetic energy formula?",["½mv²","mv","mgh","F/a"],0,"Kinetic energy equals one-half mass times speed squared.","Động năng = ½ × khối lượng × vận tốc²  (½mv²).","Động năng phụ thuộc bình phương vận tốc hay chỉ vận tốc?"],["What is cellular respiration's main purpose?",["Transfer chemical energy to ATP","Store all sunlight as glucose","Make DNA without nutrients","Convert ATP back into glucose as the only step"],0,"Cellular respiration produces ATP from food energy.","Hô hấp tế bào chuyển năng lượng hóa học trong thức ăn thành ATP.","Tế bào tạo ATP từ năng lượng thức ăn."],["What is diffusion?",["Net movement down a concentration gradient","Movement only against gradient","Cell division","Energy creation"],0,"Particles spread from higher to lower concentration on average.","Khuếch tán là các hạt di chuyển từ nơi nồng độ cao sang nơi nồng độ thấp.","Hạt di chuyển từ nơi nồng độ cao sang thấp như thế nào?"],["How do enzymes affect reactions?",["Lower activation energy","Increase atomic number","Eliminate all substrates","Stop all collisions"],0,"Enzymes speed reactions by lowering activation energy.","Enzyme làm phản ứng nhanh hơn bằng cách giảm năng lượng hoạt hóa.","Enzyme làm giảm rào cản năng lượng ban đầu."],["What is conservation of mass?",["Mass is conserved in a closed system","Mass always increases during combustion","Mass is conserved only if no chemical changes occur","Mass decreases in a closed system when gas forms"],0,"In chemical reactions in closed systems, mass remains constant.","Định luật bảo toàn khối lượng: trong hệ kín, tổng khối lượng không đổi khi phản ứng.","Tổng khối lượng trước và sau phản ứng kín có đổi không?"],["Which molecule carries oxygen in red blood cells?",["Hemoglobin","Insulin","Keratin","Chlorophyll"],0,"Hemoglobin binds oxygen for transport.","Hemoglobin trong hồng cầu gắn với oxy để vận chuyển.","Protein nào trong hồng cầu vận chuyển oxy?"],["If velocity changes, what is occurring?",["Acceleration","Motion with constant velocity","Zero acceleration in all reference frames","Force must be absent"],0,"Acceleration measures the rate of change of velocity.","Vận tốc thay đổi (về độ lớn hoặc hướng) nghĩa là có gia tốc.","Gia tốc có thể xuất hiện khi đổi hướng mà không đổi tốc độ?"],["What is an acid according to Brønsted–Lowry?",["Proton donor","Proton acceptor","Electron donor only","Neutron source"],0,"A Brønsted–Lowry acid donates H⁺.","Theo Brønsted–Lowry, axit là chất cho proton (H⁺).","Axit cho hay nhận proton H⁺?"]],"history":[["What event started World War I in Europe in 1914?",["Assassination of Archduke Franz Ferdinand","German invasion of Poland","Signing of Treaty of Versailles","Russian Revolution of 1917"],0,"The assassination triggered a diplomatic and military crisis.","Vụ ám sát Thái tử Franz Ferdinand châm ngòi khủng hoảng.","Cuộc ám sát năm 1914 liên quan đến thái tử của Áo-Hung."],["What was the Industrial Revolution?",["A transition toward machine-based industrial production","A return to cottage industries only","A political revolution ending monarchy worldwide","An expansion of primarily handcraft production"],0,"Mechanization transformed how goods were produced.","Công nghiệp hóa thay đổi cách sản xuất hàng hóa.","Cách mạng công nghiệp thay đổi sản xuất bằng loại thiết bị nào?"],["What organization was founded in 1945 to promote international cooperation?",["United Nations","League of Nations","European Union","NATO"],0,"The United Nations was founded in 1945.","Liên Hợp Quốc được thành lập năm 1945.","Tổ chức quốc tế toàn cầu được thành lập sau Thế chiến II."],["Which event occurred in 1989?",["Fall of the Berlin Wall","German reunification","Dissolution of the Soviet Union","Construction of the Berlin Wall"],0,"The Berlin Wall opened in November 1989.","Bức tường Berlin mở cửa năm 1989.","Bức tường chia cắt Berlin mở cửa cuối thập niên 1980."],["Germany invaded which country in 1939, starting World War II in Europe?",["Poland","Spain","Sweden","Portugal"],0,"Germany invaded Poland on September 1, 1939; Britain and France then declared war.","Đức tấn công Ba Lan ngày 1/9/1939, mở đầu Thế chiến II ở châu Âu.","Quốc gia này nằm ngay phía đông nước Đức."],["Which alliance included Germany and Austria-Hungary during World War I?",["Central Powers","Triple Entente","Allies with France as leader","League of Nations"],0,"Germany and Austria-Hungary formed the core of the Central Powers.","Đức và Áo-Hung là nòng cốt của phe Liên minh Trung tâm (Central Powers).","Phe Liên minh và phe Hiệp ước gồm những ai?"],["What was trench warfare?",["Combat from fortified lines of trenches","Rapid cavalry-only campaigns","Fighting primarily from open battlefields without fortifications","Naval blockades instead of land combat"],0,"Soldiers fought from extensive trench systems.","Chiến tranh chiến hào: binh lính đánh nhau từ các hệ thống hào được củng cố.","Chiến hào được đào để bảo vệ binh lính."],["Which 1917 revolution overthrew Russia's Provisional Government?",["October Revolution","February Revolution","Revolutions of 1905","Decembrist Revolt"],0,"Bolsheviks took power in the October Revolution.","Cách mạng Tháng Mười (1917): phe Bolshevik lật đổ Chính phủ Lâm thời Nga.","Chính phủ Lâm thời được lập sau cuộc cách mạng đầu năm 1917; cuộc cách mạng lật đổ nó diễn ra vào cuối năm."],["What did the Treaty of Versailles impose on Germany?",["Territorial losses and reparations","Unrestricted military expansion","The transfer of all European colonies to Germany","A peace without territorial changes"],0,"The 1919 treaty imposed major postwar terms on Germany.","Hiệp ước Versailles (1919) buộc Đức mất lãnh thổ và bồi thường chiến tranh.","Hiệp ước sau Thế chiến I buộc Đức chịu nghĩa vụ gì?"],["What was the Great Depression?",["Severe worldwide economic downturn","A short recession limited to Europe","An era of uninterrupted global growth","A crisis caused exclusively by wartime rationing"],0,"The downturn began in 1929 and lasted through much of the 1930s.","Đại Suy thoái là khủng hoảng kinh tế toàn cầu bắt đầu năm 1929, kéo dài gần hết thập niên 1930.","Khủng hoảng kinh tế diễn ra vào thập niên nào?"],["What is fascism?",["Authoritarian ultranationalist ideology","Liberal parliamentary constitutionalism","Decentralized participatory democracy","A politics emphasizing universal pacifism"],0,"Fascism promotes dictatorial rule and extreme nationalism.","Chủ nghĩa phát xít là hệ tư tưởng độc tài, dân tộc cực đoan.","Chế độ độc tài dân tộc cực đoan có tên gọi gì?"],["When did World War II end?",["1945","1918","1939","1961"],0,"World War II ended in 1945.","Thế chiến II kết thúc năm 1945.","Thế chiến II kết thúc sau năm 1939 bao nhiêu năm?"],["What was the Holocaust?",["Nazi genocide of European Jews and others","The postwar partition of Germany","A refugee resettlement agreement","The Allied invasion of Normandy"],0,"The Nazi regime and collaborators murdered six million Jews and persecuted other groups.","Holocaust là cuộc diệt chủng do Đức Quốc xã gây ra, giết hại sáu triệu người Do Thái và đàn áp nhiều nhóm khác.","Sự kiện diệt chủng do Đức Quốc xã gây ra là gì?"],["What was the main idea of containment policy?",["Limit spread of Soviet influence","Immediate invasion of the Soviet Union","Abandonment of all European alliances","Formal restoration of colonial empires"],0,"The U.S. sought to limit communist expansion during the Cold War.","Chính sách ngăn chặn: Mỹ tìm cách hạn chế ảnh hưởng của Liên Xô trong Chiến tranh Lạnh.","Chiến lược ngăn chặn hướng đến ảnh hưởng của quốc gia nào?"],["Which event is associated with 1947 Indian independence?",["End of British colonial rule","Britain tightening direct colonial administration","Formation of the British East India Company","Indian annexation by the Soviet Union"],0,"India gained independence from Britain in 1947 amid partition.","Năm 1947 Ấn Độ giành độc lập, chấm dứt sự cai trị của Anh (cùng lúc với việc chia tách Ấn Độ – Pakistan).","Ấn Độ giành độc lập khỏi đế quốc nào?"],["What is a primary source about World War II?",["A soldier's wartime letter","A recent historian's synthesis","A modern museum guide","An encyclopedia updated last year"],0,"A contemporary letter is direct evidence from the era.","Lá thư viết trong thời chiến của một người lính là tư liệu gốc từ chính thời đó.","Tư liệu gốc được tạo vào thời điểm sự kiện hay nhiều năm sau?"]],"space":[["A spacecraft travels 3.5 × 10⁴ km. How far is that?",["350 km","3,500 km","35,000 km","350,000 km"],2,"10⁴ = 10,000; 3.5 × 10,000 = 35,000 km.","10⁴ = 10.000, nên 3,5 × 10.000 = 35.000 km.","Dời dấu phẩy sang phải 4 chữ số."],["If an object’s mass is 5 kg, its weight near Earth is about...",["5 N","49 N","500 N","0.5 N"],1,"Weight = mass × g ≈ 5 × 9.8 = 49 newtons.","Trọng lượng xấp xỉ 5 × 9,8 = 49 N.","Nhân khối lượng với gia tốc trọng trường (≈ 9,8 m/s²)."],["What makes a comet’s tail generally point away from the Sun?",["Solar radiation and solar wind","Earth’s gravity","The comet’s engines","Moonlight"],0,"Solar radiation and solar wind push dust and ion tails away from the Sun.","Ánh sáng và gió Mặt Trời đẩy các đuôi sao chổi ra xa Mặt Trời.","Thứ gì liên tục thổi ra từ Mặt Trời?"],["What causes the phases of the Moon?",["Earth’s shadow each night","Our viewing angle of the sunlit Moon","Clouds around the Moon","The Moon changing shape"],1,"We see different fractions of the Moon’s illuminated side during its orbit.","Ta thấy những phần được Mặt Trời chiếu sáng khác nhau của Mặt Trăng.","Mặt Trăng không hề thay đổi hình dạng thật."],["A rocket uses 3/4 of 120 fuel units. How many units?",["30","60","90","100"],2,"Three fourths of 120 = 120 × 3 ÷ 4 = 90.","Ba phần tư của 120 bằng 90.","Tìm 1/4 trước, rồi nhân 3."],["What is a light-year?",["Time to orbit the Sun","A unit of distance","Speed of sound","Length of a calendar year"],1,"A light-year measures the distance light travels in one year.","Năm ánh sáng là đơn vị đo khoảng cách, không phải thời gian.","Tên có chữ “năm” nhưng nó không đo thời gian."],["The speed of light is about...",["3 × 10⁵ m/s","3 × 10⁸ m/s","3 × 10¹¹ m/s","3 × 10² m/s"],1,"Light travels at about 3.0 × 10⁸ meters per second in vacuum.","Ánh sáng truyền trong chân không khoảng 3 × 10⁸ m/giây.","Số 3 có 8 chữ số 0 phía sau (mét/giây)."],["A 1,200 kg spacecraft accelerates at 2 m/s². Net force?",["600 N","1,202 N","2,400 N","24,000 N"],2,"Newton’s second law: F = ma = 1,200 × 2 = 2,400 N.","Định luật II Newton: F = m × a = 2.400 N.","Nhân khối lượng với gia tốc."],["Which telescope mainly detects radio waves?",["Radio telescope","Optical refractor","Thermal camera only","Microscope"],0,"Radio telescopes receive radio-frequency electromagnetic radiation.","Kính thiên văn vô tuyến thu bức xạ điện từ ở dải sóng vô tuyến.","Nghĩ đến những chảo ăng-ten khổng lồ."],["For a satellite in uniform circular orbit, centripetal acceleration points...",["Tangent to the path","Away from the center","Toward the orbit center","Opposite its velocity always"],2,"Centripetal acceleration always points toward the center of circular motion.","Gia tốc hướng tâm luôn hướng vào tâm quỹ đạo tròn.","“Hướng tâm” nghĩa là hướng về đâu?"],["If F = 750 N acts on 250 kg, what is acceleration?",["0.33 m/s²","3 m/s²","500 m/s²","1,000 m/s²"],1,"Using F = ma gives a = F/m = 750/250 = 3 m/s².","Từ F = ma suy ra a = 750/250 = 3 m/s².","Biến đổi F = ma để tìm a."],["What does a redshift in light from a distant galaxy often indicate?",["It is approaching us","It is receding from us","It stopped emitting light","It has no stars"],1,"Cosmological redshift is associated with expansion and recession.","Dịch chuyển đỏ của thiên hà xa thường liên quan đến sự giãn nở của vũ trụ.","Bước sóng ánh sáng ta nhận được bị kéo dài ra."],["Which element makes up most of the Sun?",["Hydrogen","Iron","Oxygen","Carbon"],0,"About three-quarters of the Sun’s mass is hydrogen.","Khoảng 3/4 khối lượng Mặt Trời là hydro.","Đây là nguyên tố nhẹ nhất."],["What process powers the Sun?",["Nuclear fusion","Burning coal","Nuclear fission of uranium","Static electricity"],0,"In the core, hydrogen nuclei fuse into helium and release energy.","Trong lõi, hạt nhân hydro hợp nhất thành heli và giải phóng năng lượng.","Các hạt nhân nhỏ kết hợp lại thành hạt nhân lớn hơn."],["What is escape velocity?",["Minimum speed to break free of a body’s gravity","Top speed of a car","Speed of sound in space","Speed of a falling leaf"],0,"Escape velocity is the minimum launch speed needed to leave a body’s gravity without more thrust (about 11.2 km/s for Earth).","Vận tốc thoát ly là tốc độ tối thiểu để thoát khỏi lực hấp dẫn (khoảng 11,2 km/s với Trái Đất).","Tên gọi có chữ \"escape\" — thoát ra."]]},"10":{"math":[["Solve: x² − 5x + 6 = 0.",["x=1 or 6","x=2 or 3","x=−2 or −3","x=0 or 5"],1,"Factor (x−2)(x−3)=0.","Phân tích thành (x−2)(x−3).","Tìm hai số nhân ra 6 và cộng ra −5."],["What is the vertex of y = (x−2)² + 3?",["(−2,3)","(2,−3)","(2,3)","(3,2)"],2,"Vertex form y=(x−h)²+k has vertex (h,k).","Dạng đỉnh có tọa độ (h,k).","Trong dạng y=(x−h)²+k, đỉnh chính là (h,k)."],["What is sin(30°)?",["0","1/2","√3/2","1"],1,"In a 30°–60°–90° triangle, opposite/hypotenuse = 1/2.","Sin 30 độ bằng 1/2.","Tam giác 30–60–90 có cạnh đối góc 30° bằng nửa cạnh huyền."],["A geometric sequence starts 3, 6, 12. What is term 5?",["18","24","36","48"],3,"Double each term: 3,6,12,24,48.","Cấp số nhân có công bội 2.","Số hạng kế tiếp gấp đôi số trước."],["Solve x²−7x+10=0.",["x=2 or 5","x=−2 or −5","x=1 or 10","x=−1 or −10"],0,"Factor (x−2)(x−5)=0.","Phân tích (x − 2)(x − 5) = 0 nên x = 2 hoặc x = 5.","Tìm hai số có tích 10 và tổng 7."],["Find discriminant of 2x²−4x+3=0.",["−8","8","16","−24"],0,"b²−4ac =16−24=−8.","Δ = b² − 4ac = (−4)² − 4 × 2 × 3 = 16 − 24 = −8.","Dùng công thức Δ=b²−4ac."],["What is cos(60°)?",["1/2","√3/2","1","0"],0,"For a 60-degree angle, adjacent/hypotenuse is 1/2.","Với góc 60°, cạnh kề ÷ cạnh huyền = 1/2.","Dùng tam giác đặc biệt 30–60–90 độ."],["A geometric sequence has a₁=5, ratio 3. Find a₄.",["135","45","15","405"],0,"a₄=5×3³=135.","a₄ = 5 × 3³ = 5 × 27 = 135.","Cấp số nhân: số hạng thứ tư nhân công bội ba lần."],["A circle radius 5 cm has area (exact).",["25π cm²","10π cm²","5π cm²","50π cm²"],0,"Area = πr² =25π cm².","Diện tích = πr² = π × 5² = 25π cm².","Diện tích hình tròn là π nhân bình phương bán kính."],["What is 2^5 ÷ 2^2?",["8","4","16","32"],0,"Subtract exponents: 2³=8.","Chia cùng cơ số thì trừ số mũ: 2⁵ ÷ 2² = 2³ = 8.","Chia hai lũy thừa cùng cơ số thì trừ số mũ."],["Solve 4x+1 = 2x+9.",["4","5","6","3"],0,"Subtract 2x and 1: 2x=8, so x=4.","Trừ 2x và trừ 1 hai vế: 2x = 8, nên x = 4.","Gom x về một vế, số về vế còn lại."],["What is tan(45°)?",["1","0","1/2","√3"],0,"In a 45–45–90 triangle, opposite and adjacent legs are equal.","Tam giác vuông cân 45°–45°–90° có hai cạnh góc vuông bằng nhau nên tan 45° = 1.","Tangent bằng đối chia kề; hai cạnh góc vuông bằng nhau."],["The roots of (x−4)²=9 are ...",["x=1 or 7","x=−1 or 7","x=4 or 9","x=3 or 5"],0,"Take square roots: x−4=±3, so x=1 or 7.","Lấy căn hai vế: x − 4 = ±3, nên x = 1 hoặc x = 7.","Khi lấy căn hai vế, nhớ cả dấu cộng lẫn trừ."],["A right triangle has hypotenuse 13 and one leg 5. Other leg?",["12","8","√194","18"],0,"The other leg is √(13²−5²)=√144=12.","Cạnh còn lại = √(13² − 5²) = √144 = 12.","Bình phương cạnh còn lại bằng cạnh huyền bình phương trừ cạnh đã biết bình phương."],["Simplify (x²y³)(x⁴y).",["x⁶y⁴","x⁸y³","x⁶y³","x⁸y⁴"],0,"Add exponents on matching bases x and y.","Cộng số mũ từng biến: x²·x⁴ = x⁶, y³·y = y⁴.","Nhân các lũy thừa cùng cơ số; cộng số mũ cho từng biến."],["What is the midpoint of (2,6) and (8,10)?",["(5,8)","(6,4)","(10,16)","(3,2)"],0,"Average x values and y values: ((2+8)/2,(6+10)/2).","Trung điểm = ((2 + 8) ÷ 2, (6 + 10) ÷ 2) = (5, 8).","Lấy trung bình hai hoành độ và hai tung độ."]],"science":[["How many moles are in 18 g of water (H₂O)?",["0.5 mol","1 mol","2 mol","18 mol"],1,"Water has molar mass about 18 g/mol.","Khối lượng mol của nước (H₂O) xấp xỉ 18 g/mol.","Một mol nước có khối lượng xấp xỉ 18 gam."],["Which process creates mRNA from a DNA template?",["Translation","Transcription","Respiration","Diffusion"],1,"Transcription copies information from DNA into RNA.","Phiên mã tạo RNA từ khuôn DNA.","Từ DNA làm bản sao RNA là phiên mã hay dịch mã?"],["What is the acceleration due to gravity near Earth’s surface?",["0.98 m/s²","9.8 m/s²","98 m/s²","100 m/s²"],1,"Near Earth’s surface, g is about 9.8 m/s².","Gia tốc trọng trường khoảng 9.8 m/s².","Giá trị gia tốc rơi tự do gần mặt đất vào khoảng 10 m/s²."],["What occurs in an exothermic reaction?",["Heat is released to surroundings","Energy absorbed from the surroundings","Energy exchanged without net release","Heat is stored exclusively in chemical products"],0,"Exothermic reactions transfer heat to the surroundings.","Phản ứng tỏa nhiệt truyền nhiệt ra môi trường.","Tỏa nhiệt tức là hệ truyền nhiệt ra ngoài."],["What is molar mass of CO₂ (approx.)?",["44 g/mol","28 g/mol","16 g/mol","12 g/mol"],0,"12 for carbon plus 2×16 for oxygen equals 44.","Khối lượng mol CO₂ = 12 + 2 × 16 = 44 g/mol.","Cộng khối lượng của 1 C và 2 O."],["What is the charge on a sodium ion Na⁺?",["+1","−1","0","+2"],0,"Sodium loses one electron to become Na⁺.","Natri mất một electron nên thành ion Na⁺ mang điện tích +1.","Mất một electron làm ion mang điện tích gì?"],["What is pH of a strongly acidic solution?",["2","7","9","12"],0,"At 25°C low pH indicates acidic solutions.","pH càng nhỏ thì càng axit; pH 2 là axit mạnh.","Số pH càng nhỏ thì độ axit tăng hay giảm?"],["What are products in a chemical equation?",["Substances formed in reaction","Starting substances","Only catalysts","Only solvents"],0,"Products appear on the right side of a reaction arrow.","Sản phẩm là các chất tạo thành, nằm bên phải mũi tên phản ứng.","Chất sản phẩm nằm ở phía nào của mũi tên phản ứng?"],["What is the balanced coefficient before O₂ in 2H₂ + O₂ → 2H₂O?",["1","2","3","4"],0,"Two hydrogen molecules react with one oxygen molecule.","2 phân tử H₂ phản ứng với 1 phân tử O₂, nên hệ số trước O₂ là 1.","Đếm nguyên tử oxy hai phía rồi cân bằng."],["What is a homologous pair of chromosomes?",["Two chromosomes with corresponding genes","Two identical sister chromatids","A chromosome and its RNA copy","Any two chromosomes from different species"],0,"Homologous chromosomes carry corresponding gene locations.","Cặp nhiễm sắc thể tương đồng mang các gen tương ứng ở cùng vị trí.","Cặp nhiễm sắc thể tương đồng có các vị trí gen giống nhau."],["What occurs in meiosis?",["Haploid cells are produced","Two genetically identical diploid daughter cells","Four identical diploid body cells","Cells with twice the parent's chromosome number"],0,"Meiosis reduces chromosome number to produce haploid gametes.","Giảm phân làm số nhiễm sắc thể giảm một nửa, tạo giao tử đơn bội.","Giảm phân làm số lượng nhiễm sắc thể giảm mấy lần?"],["What is Newton's third law?",["Equal and opposite forces on different objects","Force equals mass times acceleration","An object at rest remains at rest without net force","Energy is conserved in a closed system"],0,"Interaction forces come in equal and opposite pairs.","Định luật III Newton: lực và phản lực bằng nhau, ngược chiều, tác dụng lên hai vật khác nhau.","Lực tác dụng và phản lực tác động lên cùng hay khác vật?"],["What is momentum?",["Mass times velocity","Force divided by distance","Power times area","Volume times density"],0,"Momentum p = mv.","Động lượng = khối lượng × vận tốc (p = mv).","Động lượng phụ thuộc khối lượng và vận tốc."],["If V=12 volts and R=4 ohms, current I=?",["3 A","48 A","8 A","16 A"],0,"By Ohm's law I=V/R=3 A.","Định luật Ohm: I = U ÷ R = 12 ÷ 4 = 3 A.","Dùng định luật Ohm: cường độ dòng điện = U/R."],["What is carrying capacity in ecology?",["Maximum sustainable population","Number of predators only","Energy of sunlight","Amount of rainfall only"],0,"Carrying capacity depends on resources and conditions.","Sức chứa môi trường là số cá thể tối đa mà môi trường duy trì được lâu dài.","Môi trường có thể duy trì bao nhiêu cá thể lâu dài?"],["What is the main job of ribosomes?",["Make proteins","Store water","Release energy as light","Copy the cell wall"],0,"Ribosomes read mRNA and link amino acids together to build proteins.","Ribosome đọc mRNA và nối các axit amin lại để tạo protein.","Nghĩ đến bước \"dịch mã\" sau phiên mã."]],"history":[["Which treaty is associated with the end of World War I with Germany?",["Treaty of Versailles","Treaty of Brest-Litovsk","Treaty of Saint-Germain","Treaty of Trianon"],0,"The Treaty of Versailles was signed in 1919.","Hiệp ước Versailles ký năm 1919.","Sau Thế chiến I, hiệp ước với Đức ký tại thành phố nào của Pháp?"],["What was the Cold War?",["Rivalry largely between the U.S. and Soviet Union","Direct declared total war between U.S. and Soviet armies","A trade-only disagreement with no military tensions","A conflict solely over European borders during WWI"],0,"It was a long geopolitical and ideological rivalry.","Chiến tranh Lạnh là cạnh tranh địa chính trị và ý thức hệ kéo dài.","Chiến tranh Lạnh chủ yếu xoay quanh hai siêu cường nào?"],["What does decolonization mean?",["Former colonies gaining independence","Colonial annexation of independent states","Replacing one empire with another","Increasing direct rule from imperial capitals"],0,"Decolonization is the dismantling of colonial control.","Phi thực dân hóa là chấm dứt cai trị thuộc địa.","Quá trình các thuộc địa giành quyền tự chủ được gọi là gì?"],["Which movement sought to end legal racial segregation in the United States?",["Civil Rights Movement","Progressive Era reform movement","Women's suffrage movement","Populist movement"],0,"The Civil Rights Movement worked for equal rights and against segregation.","Phong trào Dân quyền đấu tranh chống phân biệt chủng tộc.","Phong trào đấu tranh chấm dứt luật phân biệt chủng tộc tại Mỹ."],["What was the Marshall Plan?",["U.S. economic aid to rebuild postwar Europe","A Soviet economic integration program","An American nuclear deterrence plan","A European military invasion strategy"],0,"The plan supported European economic recovery after WWII.","Kế hoạch Marshall là viện trợ kinh tế của Mỹ để tái thiết châu Âu sau Thế chiến II.","Sau Thế chiến II, Hoa Kỳ hỗ trợ kinh tế cho khu vực nào?"],["What was NATO founded as in 1949?",["Collective defense alliance","A customs union of Western Europe","A global humanitarian aid agency","A postwar war-crimes tribunal"],0,"NATO is a military alliance with a mutual defense principle.","NATO (1949) là liên minh phòng thủ chung: tấn công một nước thành viên được xem là tấn công tất cả.","Các nước thành viên cam kết phòng thủ chung."],["What did the Berlin Wall symbolize?",["Cold War division of Berlin","The rebuilding of a unified Germany","The division of Europe after World War I","The creation of the European Union"],0,"The wall divided East and West Berlin for decades.","Bức tường Berlin chia cắt Đông và Tây Berlin, tượng trưng cho sự chia rẽ thời Chiến tranh Lạnh.","Bức tường chia cắt Đông và Tây tại thành phố nào?"],["When did the Berlin Wall fall?",["1989","1945","1961","1999"],0,"The Berlin Wall opened in November 1989.","Bức tường Berlin sụp đổ (mở cửa) tháng 11 năm 1989.","Sự kiện diễn ra vào cuối thập niên 1980."],["What was the Cuban Missile Crisis?",["1962 U.S.–Soviet confrontation over missiles","A 1956 uprising in Hungary","A 1968 Soviet invasion of Czechoslovakia","A 1961 dispute over the Berlin Wall"],0,"The 1962 crisis brought nuclear powers close to war.","Khủng hoảng tên lửa Cuba năm 1962 giữa Mỹ và Liên Xô suýt dẫn đến chiến tranh hạt nhân.","Khủng hoảng tên lửa xảy ra giữa Mỹ và nước nào?"],["What was apartheid in South Africa?",["Institutionalized racial segregation","A policy of universal adult suffrage","An anti-colonial regional trade bloc","A voluntary cultural separation without legal force"],0,"Apartheid enforced racist segregation and political exclusion.","Apartheid là chế độ phân biệt chủng tộc được luật pháp hóa ở Nam Phi.","Chính sách apartheid phân biệt con người dựa vào yếu tố nào?"],["Who became South Africa's first Black president in 1994?",["Nelson Mandela","Desmond Tutu","Frederik de Klerk","Kwame Nkrumah"],0,"Mandela was elected president in 1994.","Nelson Mandela được bầu làm tổng thống da đen đầu tiên của Nam Phi năm 1994.","Lãnh đạo chống chế độ apartheid nổi tiếng là ai?"],["What was the Non-Aligned Movement?",["States seeking independence from major Cold War blocs","A military union of NATO member states","A Soviet-sponsored economic council","A treaty that divided Germany"],0,"Members sought alternatives to alignment with major blocs.","Phong trào Không liên kết gồm các nước không muốn theo phe Mỹ hay phe Liên Xô.","Trong Chiến tranh Lạnh, phong trào này không muốn bị ràng buộc với phe nào?"],["In what year was the Universal Declaration of Human Rights adopted?",["1948","1918","1776","1989"],0,"The U.N. General Assembly adopted it in 1948.","Đại hội đồng Liên Hợp Quốc thông qua Tuyên ngôn Quốc tế Nhân quyền năm 1948.","Văn kiện nhân quyền ra đời ngay sau Thế chiến nào?"],["Which event occurred in 1969?",["First crewed Moon landing","Fall of Berlin Wall","Signing of U.S. Constitution","End of World War I"],0,"Apollo 11 landed humans on the Moon in 1969.","Năm 1969, tàu Apollo 11 đưa con người đặt chân lên Mặt Trăng lần đầu tiên.","Apollo 11 đặt chân lên Mặt Trăng năm nào?"],["What does globalization describe?",["Increasing worldwide interconnectedness","Economic self-sufficiency of all states","The end of international communication","Countries removing all foreign trade"],0,"Globalization links economies, cultures, and communications.","Toàn cầu hóa là sự kết nối ngày càng chặt chẽ giữa các nước về kinh tế, văn hóa và thông tin.","Thương mại, văn hóa và công nghệ kết nối các nước như thế nào?"],["What is a reliable approach to competing historical claims?",["Compare evidence and source context","Accept only the oldest source","Prefer interpretations without evidence","Treat source bias as irrelevant"],0,"Evaluation of origin, evidence, and context improves historical reasoning.","Khi các nguồn mâu thuẫn, hãy so sánh bằng chứng và bối cảnh (ai viết, khi nào, vì sao).","Khi các nguồn mâu thuẫn, nên kiểm tra chứng cứ nào?"]],"space":[["A spacecraft travels 3.5 × 10⁴ km. How far is that?",["350 km","3,500 km","35,000 km","350,000 km"],2,"10⁴ = 10,000; 3.5 × 10,000 = 35,000 km.","10⁴ = 10.000, nên 3,5 × 10.000 = 35.000 km.","Dời dấu phẩy sang phải 4 chữ số."],["If an object’s mass is 5 kg, its weight near Earth is about...",["5 N","49 N","500 N","0.5 N"],1,"Weight = mass × g ≈ 5 × 9.8 = 49 newtons.","Trọng lượng xấp xỉ 5 × 9,8 = 49 N.","Nhân khối lượng với gia tốc trọng trường (≈ 9,8 m/s²)."],["What makes a comet’s tail generally point away from the Sun?",["Solar radiation and solar wind","Earth’s gravity","The comet’s engines","Moonlight"],0,"Solar radiation and solar wind push dust and ion tails away from the Sun.","Ánh sáng và gió Mặt Trời đẩy các đuôi sao chổi ra xa Mặt Trời.","Thứ gì liên tục thổi ra từ Mặt Trời?"],["What causes the phases of the Moon?",["Earth’s shadow each night","Our viewing angle of the sunlit Moon","Clouds around the Moon","The Moon changing shape"],1,"We see different fractions of the Moon’s illuminated side during its orbit.","Ta thấy những phần được Mặt Trời chiếu sáng khác nhau của Mặt Trăng.","Mặt Trăng không hề thay đổi hình dạng thật."],["A rocket uses 3/4 of 120 fuel units. How many units?",["30","60","90","100"],2,"Three fourths of 120 = 120 × 3 ÷ 4 = 90.","Ba phần tư của 120 bằng 90.","Tìm 1/4 trước, rồi nhân 3."],["What is a light-year?",["Time to orbit the Sun","A unit of distance","Speed of sound","Length of a calendar year"],1,"A light-year measures the distance light travels in one year.","Năm ánh sáng là đơn vị đo khoảng cách, không phải thời gian.","Tên có chữ “năm” nhưng nó không đo thời gian."],["The speed of light is about...",["3 × 10⁵ m/s","3 × 10⁸ m/s","3 × 10¹¹ m/s","3 × 10² m/s"],1,"Light travels at about 3.0 × 10⁸ meters per second in vacuum.","Ánh sáng truyền trong chân không khoảng 3 × 10⁸ m/giây.","Số 3 có 8 chữ số 0 phía sau (mét/giây)."],["A 1,200 kg spacecraft accelerates at 2 m/s². Net force?",["600 N","1,202 N","2,400 N","24,000 N"],2,"Newton’s second law: F = ma = 1,200 × 2 = 2,400 N.","Định luật II Newton: F = m × a = 2.400 N.","Nhân khối lượng với gia tốc."],["Which telescope mainly detects radio waves?",["Radio telescope","Optical refractor","Thermal camera only","Microscope"],0,"Radio telescopes receive radio-frequency electromagnetic radiation.","Kính thiên văn vô tuyến thu bức xạ điện từ ở dải sóng vô tuyến.","Nghĩ đến những chảo ăng-ten khổng lồ."],["For a satellite in uniform circular orbit, centripetal acceleration points...",["Tangent to the path","Away from the center","Toward the orbit center","Opposite its velocity always"],2,"Centripetal acceleration always points toward the center of circular motion.","Gia tốc hướng tâm luôn hướng vào tâm quỹ đạo tròn.","“Hướng tâm” nghĩa là hướng về đâu?"],["If F = 750 N acts on 250 kg, what is acceleration?",["0.33 m/s²","3 m/s²","500 m/s²","1,000 m/s²"],1,"Using F = ma gives a = F/m = 750/250 = 3 m/s².","Từ F = ma suy ra a = 750/250 = 3 m/s².","Biến đổi F = ma để tìm a."],["What does a redshift in light from a distant galaxy often indicate?",["It is approaching us","It is receding from us","It stopped emitting light","It has no stars"],1,"Cosmological redshift is associated with expansion and recession.","Dịch chuyển đỏ của thiên hà xa thường liên quan đến sự giãn nở của vũ trụ.","Bước sóng ánh sáng ta nhận được bị kéo dài ra."],["Which element makes up most of the Sun?",["Hydrogen","Iron","Oxygen","Carbon"],0,"About three-quarters of the Sun’s mass is hydrogen.","Khoảng 3/4 khối lượng Mặt Trời là hydro.","Đây là nguyên tố nhẹ nhất."],["What process powers the Sun?",["Nuclear fusion","Burning coal","Nuclear fission of uranium","Static electricity"],0,"In the core, hydrogen nuclei fuse into helium and release energy.","Trong lõi, hạt nhân hydro hợp nhất thành heli và giải phóng năng lượng.","Các hạt nhân nhỏ kết hợp lại thành hạt nhân lớn hơn."],["What is escape velocity?",["Minimum speed to break free of a body’s gravity","Top speed of a car","Speed of sound in space","Speed of a falling leaf"],0,"Escape velocity is the minimum launch speed needed to leave a body’s gravity without more thrust (about 11.2 km/s for Earth).","Vận tốc thoát ly là tốc độ tối thiểu để thoát khỏi lực hấp dẫn (khoảng 11,2 km/s với Trái Đất).","Tên gọi có chữ \"escape\" — thoát ra."]]}};
